import type { BankQuestion } from "@/lib/bank";

/** Arrays, Strings, Linked Lists, Stacks, Queues and Hashing (Data Structures & Algorithms): 214 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cs-dsa-linear-1", "question": "What is the time complexity of reading the element arr[i] from an array of n elements, given i?", "options": ["O(1)", "O(n)", "O(log n)", "O(i)"], "answer": 0, "explanation": "Array elements sit in contiguous memory, so the address is base + i × size and is computed in constant time. O(i) would be the cost of reaching the i-th node of a linked list, not an array.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-2","question":"Which data structure works on the Last In, First Out (LIFO) principle?","options":["Queue","Stack","Priority queue","Hash table"],"answer":1,"explanation":"A stack removes the most recently pushed item first (LIFO). A queue is FIFO, and a priority queue removes by priority, not by arrival order.","difficulty":"easy","source":"Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-3","question":"What is the worst-case time complexity of binary search on a sorted array of n elements?","options":["O(n log n)","O(1)","O(log n)","O(n)"],"answer":2,"explanation":"Each comparison halves the search range, so at most about log₂ n + 1 comparisons are needed: O(log n). O(n) is linear search.","difficulty":"easy","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-dsa-linear-4","question":"Which of these sorting algorithms is stable in its standard implementation?","options":["Quick sort","Selection sort","Heap sort","Merge sort"],"answer":3,"explanation":"Standard merge sort takes from the left half on ties, so equal keys keep their order. Quick sort, heap sort and selection sort can all swap equal keys past each other over long distances.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-5", "question": "What is the time complexity of inserting a new node at the head of a singly linked list of n nodes?", "options": ["O(1)", "O(n)", "O(log n)", "O(n²)"], "answer": 0, "explanation": "Point the new node's next at the current head and make the new node the head: two pointer assignments, O(1). Inserting at the tail without a tail pointer is O(n).", "difficulty": "easy", "source": "HCL · Tech Mahindra pattern"},
  {"id": "cs-dsa-linear-6", "question": "With a good hash function and a bounded load factor, what is the average time to search for a key in a hash table?", "options": ["O(n log n)", "O(1)", "O(n)", "O(log n)"], "answer": 1, "explanation": "With keys spread evenly and the load factor kept constant, each bucket holds O(1) keys on average, so search is O(1) on average. The worst case, when all keys collide, is still O(n).", "difficulty": "easy", "source": "IBM · Deloitte pattern"},
  {"id": "cs-dsa-linear-7", "question": "What is the postfix form of the infix expression A + B * C?", "options": ["A B C + *", "A B + C *", "+ A * B C", "A B C * +"], "answer": 3, "explanation": "* has higher precedence than +, so B * C is grouped first: A (B C *) + gives A B C * +. A B + C * would be the postfix of (A + B) * C.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-8","question":"What is the value of the postfix expression 6 2 3 + − 3 8 2 / + * ?","options":["-7","49","7","1"],"answer":2,"explanation":"2 3 + = 5; 6 − 5 = 1; 8 2 / = 4; 3 + 4 = 7; finally 1 × 7 = 7. Popping the operands in the wrong order gives 5 − 6 = −1 and hence −7.","difficulty":"moderate","source":"Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-9", "question": "A circular queue is implemented in an array of size 10 and one slot is always kept empty so that 'full' and 'empty' can be told apart. How many elements can the queue hold at most?", "options": ["10", "11", "5", "9"], "answer": 3, "explanation": "With front == rear meaning empty, 'full' is defined as (rear + 1) mod N == front, so one slot stays unused and the capacity is N − 1 = 9.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id":"cs-dsa-linear-10","question":"Keys 23, 43, 13 and 27 are inserted in that order into an empty hash table of size 10 with h(k) = k mod 10 and linear probing. At which index does 13 end up?","options":["5","3","7","4"],"answer":0,"explanation":"23 → 3; 43 → 3 is taken, goes to 4; 13 → 3 and 4 are taken, goes to 5; 27 → 7. Index 3 is only its home slot, not where it is stored.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-11","question":"For A = [3, 1, 4, 1, 5, 9, 2, 6] (0-based), the prefix array is P[0] = 0 and P[i] = A[0] + … + A[i−1]. Which expression gives the sum A[2] + A[3] + A[4] + A[5], and what is it?","options":["P[6] − P[1] = 20","P[6] − P[2] = 19","P[5] − P[2] = 10","P[5] − P[1] = 11"],"answer":1,"explanation":"With this convention the sum of A[l..r] is P[r + 1] − P[l] = P[6] − P[2] = 23 − 4 = 19 (that is, 4 + 1 + 5 + 9). Using P[r] − P[l] drops the last element and gives 10.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-12","question":"Linear search looks for a key that is NOT in an unsorted array of 100 elements. How many key comparisons does it make?","options":["50","99","100","7"],"answer":2,"explanation":"To be sure the key is absent, every one of the 100 elements must be compared. 50 is the average for a successful search; 7 is the binary-search figure, which needs sorted data.","difficulty":"easy","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dsa-linear-13","question":"What is the minimum number of stacks needed to implement a queue, if no other data structure may be used?","options":["1","4","3","2"],"answer":3,"explanation":"One stack receives enqueued items; when the other (output) stack is empty, everything is popped across, reversing the order so the oldest item is on top. A single stack can only give LIFO order.","difficulty":"easy","source":"Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-14","question":"What is the prefix (Polish) form of (A + B) * (C − D)?","options":["* + A B − C D","* A B + − C D","A B + C D − *","+ A B * − C D"],"answer":0,"explanation":"The last operator applied is *, so it comes first, followed by the prefix forms of its two operands: + A B and − C D. A B + C D − * is the postfix form.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-dsa-linear-15","question":"Bubble sort is written with a flag that stops it when a full pass makes no swap. What is its time complexity on an array that is already sorted?","options":["O(1)","O(n)","O(n²)","O(n log n)"],"answer":1,"explanation":"The first pass makes n − 1 comparisons and no swap, so the algorithm stops: O(n). Without the flag it would still run all passes and take O(n²).","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-16","question":"Kadane's algorithm is run on [3, −4, 5, −1, 2, −6, 4]. What maximum contiguous subarray sum does it return?","options":["7","4","6","5"],"answer":2,"explanation":"The best subarray is [5, −1, 2] with sum 6. Running sums restart after 3 − 4 = −1 < 0; then 5, 4, 6 (best), 0, 4. Adding all the positives (3 + 5 + 2 + 4 = 14) ignores the contiguity requirement.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-17","question":"What is the auxiliary space used by the standard top-down merge sort on an array of n elements?","options":["O(log n)","O(1)","O(n log n)","O(n)"],"answer":3,"explanation":"Merging needs a temporary array of up to n elements; the recursion stack adds only O(log n), so the total is O(n). O(log n) is the stack space of a well-implemented quick sort.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id":"cs-dsa-linear-18","question":"In a singly linked list you are given only a pointer to a node X (not the last node) and no head pointer. How can X be deleted, and in what time?","options":["Copy the next node's data into X and unlink the next node: O(1)","It cannot be deleted without the head pointer","Traverse from the head to X's predecessor: O(n)","Swap X with the tail node: O(n)"],"answer":0,"explanation":"X takes over its successor's data and next pointer, and the successor is freed, which is O(1). The trick fails only for the last node, which is why the question excludes it.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-19", "question": "Which of these is NOT a typical application of a stack?", "options": ["Managing function calls (call stack)", "Breadth-first search of a graph", "Undo in a text editor", "Checking balanced parentheses"], "answer": 1, "explanation": "BFS visits vertices level by level and needs a FIFO queue. Parenthesis matching, the call stack and undo all need the most recent item first, which is what a stack provides.", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-20", "question": "A sorted array of n integers is given. Using the two-pointer technique, what are the time and extra space needed to decide whether some pair sums to a target T?", "options": ["O(n²) time, O(1) space", "O(n) time, O(n) space", "O(n) time, O(1) space", "O(n log n) time, O(1) space"], "answer": 2, "explanation": "Start with pointers at both ends; if the sum is too small move the left pointer right, if too large move the right pointer left. Each step discards one element, giving O(n) time and two variables of space; the hash-set method is also O(n) time but needs O(n) space.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-21", "question": "The numbers 1, 2, 3, 4, 5 are pushed onto a stack in that order, and pops may happen at any time in between. Which output sequence is IMPOSSIBLE?", "options": ["1 2 3 4 5", "3 2 5 4 1", "4 5 3 2 1", "3 1 2 5 4"], "answer": 3, "explanation": "To output 3 first, 1 and 2 must already be on the stack with 2 above 1, so 1 cannot come out before 2. The other three can be produced, e.g. 3 2 5 4 1 is push 1,2,3, pop, pop, push 4,5, pop, pop, pop.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-22","question":"Keys 15, 11, 27, 8, 12, 22, 29, 1 are inserted into a hash table of size 7 with h(k) = k mod 7 and separate chaining. What is the length of the longest chain?","options":["5","3","4","2"],"answer":0,"explanation":"15, 8, 22, 29 and 1 all leave remainder 1 when divided by 7, so slot 1 holds a chain of 5; 11 → 4, 27 → 6, 12 → 5 are alone. Missing 1 mod 7 = 1 gives the tempting 4.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-dsa-linear-23","question":"Keys 22, 33 and 44 are inserted in that order into an empty table of size 11 with h(k) = k mod 11 and quadratic probing hᵢ(k) = (h(k) + i²) mod 11. At which index is 44 placed?","options":["2","4","1","3"],"answer":1,"explanation":"All three keys hash to 0. 22 → 0; 33 tries 0, then 0 + 1 = 1; 44 tries 0, 1 (both full), then 0 + 4 = 4. Linear probing would have put 44 at 2.","difficulty":"hard","source":"Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-24","question":"Two sorted lists of 5 and 7 elements are merged by the standard merge procedure. What is the maximum number of comparisons it can make?","options":["12","35","11","7"],"answer":2,"explanation":"Every comparison outputs one element, and once one list runs out the rest is copied without comparing, so at most m + n − 1 = 11 comparisons are made (when the lists interleave to the end). The minimum is min(m, n) = 5.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-25","question":"A fixed-size sliding window of length 3 moves over [2, 1, 5, 1, 3, 2, 9, 1]. What is the largest window sum?","options":["15","9","12","14"],"answer":3,"explanation":"Window sums are 8, 7, 9, 6, 14, 12 (each new sum = previous + entering element − leaving element), so the maximum is 3 + 2 + 9 = 14. 12 is the last window, 2 + 9 + 1.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-26","question":"How many element shifts does insertion sort perform to sort [4, 3, 2, 10, 12, 1, 5, 6] in ascending order?","options":["12","13","8","15"],"answer":0,"explanation":"Each shift fixes exactly one inversion, so shifts = number of inversions = 3 (from 4) + 2 (from 3) + 1 (from 2) + 3 (from 10) + 3 (from 12) = 12. 8 is the number of elements, not of shifts.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id": "cs-dsa-linear-27", "question": "Quick sort with the Lomuto partition (pivot = last element) is run on an already sorted array of 10 distinct elements. How many element-to-pivot comparisons does it make?", "options": ["10", "45", "34", "90"], "answer": 1, "explanation": "The pivot is always the largest element, so each partition removes just one element: 9 + 8 + … + 1 = 10 × 9/2 = 45 comparisons, the O(n²) worst case. About 34 would be n log₂ n for balanced splits.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-28","question":"Binary search (one three-way comparison per probe) is done on a sorted array of 1000 elements. What is the maximum number of probes needed?","options":["9","500","10","11"],"answer":2,"explanation":"The worst case is ⌊log₂ n⌋ + 1 = ⌊9.97⌋ + 1 = 10 probes, because 2¹⁰ − 1 = 1023 ≥ 1000 while 2⁹ − 1 = 511 is too small. Taking ⌊log₂ 1000⌋ = 9 forgets the final probe.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-dsa-linear-29","question":"This code tries to reverse the singly linked list 1 → 2 → 3 → 4, but its last line has been changed from cur = nxt. What does the list starting at head contain afterwards?\n```python\nprev, cur = None, head\nwhile cur:\n    nxt = cur.next\n    cur.next = prev\n    prev = cur\n    cur = cur.next\nhead = prev\n```","options":["The loop never ends","4 → 3 → 2 → 1","1 → 2 → 3 → 4","Only 1"],"answer":3,"explanation":"By the time cur = cur.next runs, cur.next has already been set to prev (None), so the loop stops after one pass. head becomes node 1 with next = None, and nodes 2–4 are lost.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-30","question":"A linked list has 3 nodes before the loop starts and a loop of 5 nodes. Floyd's slow pointer moves 1 step and fast pointer 2 steps per move, both starting at the head. After how many moves do they first meet?","options":["5","8","15","3"],"answer":0,"explanation":"After k moves slow is k steps in and fast 2k; they meet when k ≥ 3 (slow is in the loop) and 2k − k = k is a multiple of 5, so k = 5. 8 = 3 + 5 is the total number of nodes, not the meeting time.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-31","question":"^ is exponentiation (highest precedence, right-associative). What is the postfix form of A + B * C ^ D ^ E − F?","options":["A B C D ^ E ^ * + F −","A B C D E ^ ^ * + F −","A B C D E ^ ^ * F − +","A B C * D ^ E ^ + F −"],"answer":1,"explanation":"C ^ D ^ E = C ^ (D ^ E) → C D E ^ ^; times B → B C D E ^ ^ *; then A + that, and − F last because + and − are left-associative. Treating ^ as left-associative gives C D ^ E ^.","difficulty":"hard","source":"Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-32","question":"What is the value of the postfix expression 2 3 2 ^ ^ (^ means power)?","options":["81","36","512","64"],"answer":2,"explanation":"Scanning: push 2, 3, 2; the first ^ pops 3 and 2 → 3² = 9; the second ^ pops 2 and 9 → 2⁹ = 512. Getting 64 means computing (2³)², which postfix order does not do.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-33", "question": "What is the minimum stack size needed to evaluate the postfix expression a b c d + * e f − / + ?", "options": ["3", "5", "4", "11"], "answer": 2, "explanation": "Stack depth after each token: 1, 2, 3, 4 (after d), 3, 2, 3, 4 (after f), 3, 2, 1. The peak is 4, so a stack of 4 is enough.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-dsa-linear-34","question":"A queue is built from two stacks: enqueue pushes onto stack IN; dequeue pops from stack OUT, first moving everything from IN to OUT only when OUT is empty. What is the amortised cost per operation over any sequence of n operations?","options":["O(√n)","O(n)","O(log n)","O(1)"],"answer":3,"explanation":"Each element is pushed to IN once, moved to OUT once and popped once, so n operations do O(n) work in total: O(1) amortised. A single dequeue can still cost O(n) in the worst case.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-35","question":"An array has only 0s, 1s and 2s. The Dutch National Flag algorithm sorts it in one pass. What are its time and extra space?","options":["O(n) time, O(1) space","O(n²) time, O(1) space","O(n log n) time, O(1) space","O(n) time, O(n) space"],"answer":0,"explanation":"Three pointers (low, mid, high) split the array into 0s, unknown, and 2s; each step shrinks the unknown part by one, so it runs in O(n) time with only a few variables of extra space.","difficulty":"moderate","source":"Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-36","question":"n integers, each in the range 0 to n² − 1, must be sorted. Which approach sorts them in O(n) time?","options":["Heap sort","Radix sort with base n (2 passes of counting sort)","Counting sort directly on values 0 to n² − 1","Merge sort"],"answer":1,"explanation":"Written in base n each key has 2 digits, and each digit pass is a counting sort over n buckets, so the total is O(2(n + n)) = O(n). Counting sort directly needs an O(n²)-sized count array, and comparison sorts need Ω(n log n).","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-37","question":"How many comparisons does top-down merge sort (split in halves, stop comparing when one side runs out) make on [5, 1, 7, 3, 20, 15, 30, 25]?","options":["24","17","13","16"],"answer":2,"explanation":"Four pair merges take 1 each (4). [1,5] with [3,7] takes 3; [15,20] with [25,30] takes 2 (the left side runs out). The final merge of [1,3,5,7] with [15,20,25,30] takes only 4, so 4 + 5 + 4 = 13. 17 is the worst case for 8 elements, not this input.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-38", "question": "1800 keys are stored in a hash table with 600 slots using separate chaining and simple uniform hashing. About how many key comparisons does a successful search make on average?", "options": ["3", "4", "1.5", "2.5"], "answer": 3, "explanation": "Load factor α = 1800/600 = 3. A successful search scans about half of the other keys in its chain plus itself: 1 + α/2 = 2.5. An unsuccessful search would scan a whole chain, α = 3.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id": "cs-dsa-linear-39", "question": "How many distinct non-empty substrings does the string ABAB have?", "options": ["7", "8", "6", "10"], "answer": 0, "explanation": "There are 4 × 5/2 = 10 substrings by position, but A, B and AB each appear twice, so the distinct ones are A, B, AB, BA, ABA, BAB, ABAB = 7.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-40","question":"What is the KMP failure (LPS) array for the pattern AABAACAABAA?","options":["0 1 0 0 1 0 1 2 3 4 5","0 1 0 1 2 0 1 2 3 4 5","0 1 0 1 2 1 1 2 3 4 5","0 1 0 1 2 0 1 2 3 4 4"],"answer":1,"explanation":"LPS[i] is the length of the longest proper prefix of P[0..i] that is also its suffix. After C (no match, 0) the string AABAA repeats from the start, giving 1, 2, 3, 4, 5 for the last five positions.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-41","question":"The reversal algorithm rotates an array LEFT by k: reverse the first k elements, reverse the rest, then reverse the whole array. What is [1, 2, 3, 4, 5, 6, 7] after this with k = 3?","options":["3 2 1 7 6 5 4","7 6 5 4 3 2 1","4 5 6 7 1 2 3","5 6 7 1 2 3 4"],"answer":2,"explanation":"Step 1: 3 2 1 4 5 6 7; step 2: 3 2 1 7 6 5 4; step 3: 4 5 6 7 1 2 3, a left rotation by 3. 5 6 7 1 2 3 4 is a right rotation by 3 (left by 4).","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-42","question":"Which statement about a doubly linked list compared with a singly linked list is FALSE?","options":["Deleting a node given only a pointer to it is O(1)","The list can be traversed backwards from the tail","Each node needs an extra pointer field","Searching for a key becomes O(log n) because traversal can go both ways"],"answer":3,"explanation":"Search is still a linear scan, O(n); two directions do not allow halving because there is no random access. The other three are true benefits and costs of the prev pointer.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-43", "question": "How many of these statements are correct?\n(i) Merge sort is stable.\n(ii) Heap sort runs in O(n log n) even in the worst case.\n(iii) Quick sort with a randomly chosen pivot runs in O(n log n) in the worst case.\n(iv) Insertion sort runs in O(n) on an already sorted array.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(i), (ii) and (iv) are true. (iii) is false: random pivots give O(n log n) expected time, but a run of bad pivots can still cost O(n²), so the worst case is unchanged.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-44","question":"What is the time complexity of this code fragment?\n```c\nint count = 0;\nfor (int i = 1; i < n; i *= 2)\n    for (int j = 0; j < i; j++)\n        count++;\n```","options":["O(n)","O(n log n)","O(n²)","O(log n)"],"answer":0,"explanation":"The inner loop runs 1 + 2 + 4 + … up to below n times, a geometric series under 2n (for n = 1024 it is exactly 1023), so the total is O(n). O(n log n) comes from wrongly multiplying log n outer iterations by n.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-45","question":"What is the time complexity of this code fragment?\n```c\nfor (int i = 1; i <= n; i++)\n    for (int j = i; j <= n; j += i)\n        work();   // O(1)\n```","options":["O(n √n)","O(n log n)","O(n)","O(n²)"],"answer":1,"explanation":"For each i the inner loop runs about n/i times, so the total is n(1 + 1/2 + … + 1/n) = n·Hₙ ≈ n ln n = O(n log n). The step j += i is what stops it being O(n²).","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-46","question":"What value of count does this code print for n = 16?\n```c\nint count = 0;\nfor (int i = n; i > 0; i /= 2)\n    for (int j = 0; j < i; j++)\n        count++;\nprintf(\"%d\", count);\n```","options":["80","16","31","64"],"answer":2,"explanation":"The inner loop runs i times for i = 16, 8, 4, 2, 1 (integer division ends at 0), giving 31, which is O(n). 80 = 16 × 5 assumes the inner loop always runs n times.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-47","question":"What does this code print?\n```c\nint c = 0, n = 10;\nfor (int i = 0; i < n; i++)\n    for (int j = i + 1; j < n; j++)\n        for (int k = j + 1; k < n; k++)\n            c++;\nprintf(\"%d\", c);\n```","options":["720","1000","165","120"],"answer":3,"explanation":"Each increment matches one choice of indices i < j < k from 0..9, so c = C(10, 3) = 120. 165 = C(11, 3) is an off-by-one; 720 counts ordered triples (10 × 9 × 8).","difficulty":"hard","source":"Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-48","question":"Keys 12, 22, 32 are inserted into a size-10 table with h(k) = k mod 10 and linear probing. Then 22 is deleted by simply setting its slot back to EMPTY. What happens when we now search for 32?","options":["The search stops at the empty slot 3 and wrongly reports 32 as absent","The search loops forever","32 is found at slot 3 because the deletion shifted it","32 is found at slot 4 after 3 probes"],"answer":0,"explanation":"12 → 2, 22 → 3, 32 → 4. Search for 32 starts at 2, then hits slot 3, which is now EMPTY, and stops: false 'not found'. That is why open addressing uses a DELETED (tombstone) marker or rehashes the cluster.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-49", "question": "Keys 18, 41, 22, 44, 59, 32, 31, 96 are inserted in that order into a table of size 13 by double hashing: h₁(k) = k mod 13, h₂(k) = 7 − (k mod 7), probe i at (h₁ + i·h₂) mod 13. At which index is 96 stored?", "options": ["0", "11", "12", "8"], "answer": 1, "explanation": "Before 96 the table holds 31→0, 41→2, 18→5, 32→6, 59→7, 22→9, 44→10 (44 and 31 collided at 5). For 96, h₁ = 5 and h₂ = 7 − 5 = 2, so it tries 5, 7, 9 (all full) and lands at 11. Linear probing from 5 would have stopped at 8.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-50", "question": "1, 2, 3, 4 are pushed onto a stack in this order, with pops allowed at any time. How many of the 24 permutations can be produced as the pop sequence?", "options": ["24", "16", "14", "10"], "answer": 2, "explanation": "The valid push/pop orders are counted by the Catalan number C₄ = (1/5)·C(8, 4) = 14, and a brute-force check over all 24 orders gives the same. Ten permutations, such as 3 1 2 4, are impossible.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-51","question":"A queue uses two stacks: enqueue pushes onto IN; dequeue pops from OUT, first moving ALL of IN into OUT only if OUT is empty. For enq 1, enq 2, enq 3, deq, enq 4, deq, enq 5, deq, deq, how many single-element moves from IN to OUT happen in total?","options":["7","4","3","5"],"answer":3,"explanation":"The first deq moves 3 elements (1, 2, 3) and returns 1; the next two deqs find OUT non-empty and return 2, 3; the fourth deq finds OUT empty and moves 4 and 5, then returns 4. Total 3 + 2 = 5. Moving on every dequeue would give more.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-52", "question": "What is the postfix form of (A + B) * C − (D − E) * (F + G)?", "options": ["A B C + * D E − F G + * −", "A B + C * D E − − F G + *", "A B + C * D E − F G + * −", "A B + C D E − * F G + * −"], "answer": 2, "explanation": "Left operand of the main −: (A + B) * C → A B + C *. Right operand: (D − E) * (F + G) → D E − F G + *. Then the − goes last.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-53", "question": "What is the value of the prefix expression − * + 2 3 4 / 8 2 ?", "options": ["16", "4", "18", "-16"], "answer": 0, "explanation": "Reading it as a tree: −( *( +(2, 3), 4 ), /(8, 2) ) = (5 × 4) − 4 = 16. Scanning right to left with a stack, the first popped value is the LEFT operand; swapping them gives 4 − 20 = −16.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-54", "question": "Infix A * (B + C * (D − E)) / F is converted to postfix with an operator stack (operators and '(' are pushed onto it). What is the largest number of items on the stack at any moment?", "options": ["3", "6", "4", "5"], "answer": 1, "explanation": "After reading the second '(' the stack holds *, (, +, *, ( (5 items), and pushing − makes 6. The output is A B C D E − * + * F /. Counting only operators and forgetting the parentheses gives 4.", "difficulty": "hard", "source": "IBM · Deloitte pattern"},
  {"id": "cs-dsa-linear-55", "question": "Using a sliding window, find the length of the longest substring with no repeated character in the string dvdfabcda.", "options": ["5", "7", "6", "4"], "answer": 2, "explanation": "The window vdfabc (positions 1–6) has 6 distinct letters; extending to d repeats d, and fabcd after moving the left edge has only 5. Moving the left edge only to l + 1 instead of past the earlier copy can lead to wrong answers like 7.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-56", "question": "What is the length of the shortest contiguous subarray of [1, 4, 4, 2, 3, 1, 5] whose sum is at least 9?", "options": ["4", "2", "1", "3"], "answer": 3, "explanation": "No two adjacent elements reach 9 (the largest pair sum is 4 + 4 = 8, then 6 for 1 + 5), while 1 + 4 + 4 = 9 and 3 + 1 + 5 = 9 give length 3. Picking 4 and 5 for length 2 ignores contiguity.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-57","question":"How many contiguous subarrays of [1, 2, 3, −3, 3, 1] have sum exactly 3? (A prefix-sum + hash-map method counts them in O(n).)","options":["5","4","3","6"],"answer":0,"explanation":"Prefix sums are 0, 1, 3, 6, 3, 6, 7, and each earlier prefix that is 3 less than a later one marks a subarray: 0 → both 3s (2), the first 3 → both 6s (2), the second 3 → the last 6 (1), total 5. They are [0..1], [0..3], [2], [2..4], [4]; missing the ones that cross the −3 gives 3 or 4.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-58","question":"How many UNIQUE triplets (as sets of values, ignoring order) of [−1, 0, 1, 2, −1, −4, −2, 3] sum to 0? (Sort + two pointers, skipping duplicates.)","options":["6","5","4","7"],"answer":1,"explanation":"The unique triplets are (−4, 1, 3), (−2, −1, 3), (−2, 0, 2), (−1, −1, 2) and (−1, 0, 1), so 5. Without skipping the repeated −1, triplets such as (−1, 0, 1) and (−2, −1, 3) are found once for each −1 and the count comes out as 7.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-59","question":"What is the time complexity of this Java method?\n```java\nString build(int n) {\n    String s = \"\";\n    for (int i = 0; i < n; i++)\n        s = s + \"a\";\n    return s;\n}\n```","options":["O(1)","O(n)","O(n²)","O(n log n)"],"answer":2,"explanation":"Java Strings are immutable, so each s + \"a\" copies the current i characters into a new String: 1 + 2 + … + n = n(n + 1)/2 character copies, O(n²). A StringBuilder would make it O(n) amortised.","difficulty":"hard","source":"Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-60","question":"In Python, a list q is used as a queue: items are added with q.append(x) and removed with q.pop(0). If n items pass through the queue, which statement is correct?","options":["append is O(n), so the cost is dominated by appends","The total cost is O(n) because both operations are O(1)","pop(0) is O(log n), so the total is O(n log n)","The total cost is O(n²) because pop(0) shifts all remaining items; collections.deque.popleft() would make it O(n)"],"answer":3,"explanation":"A Python list is a dynamic array: pop(0) moves every remaining element one place left, which is O(n) each time. deque is a linked block structure with O(1) operations at both ends; append on a list is O(1) amortised.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-61","question":"What does this function print for the list 1 → 2 → 3 → 4 → 5 → 6?\n```python\ndef f(node):\n    if node is None:\n        return\n    if node.next:\n        f(node.next.next)\n    print(node.val, end=\" \")\n\nf(head)\n```","options":["5 3 1","2 4 6","6 4 2","1 3 5"],"answer":0,"explanation":"f(1) calls f(3), which calls f(5); 5.next is 6 and 6.next is None, so f(None) returns. Printing happens after the call, as the recursion unwinds: 5, then 3, then 1. Printing before the call would give 1 3 5.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-62", "question": "slow and fast both start at the head of 1 → 2 → 3 → 4 → 5 → 6. Loop A: while (fast && fast->next) { slow = slow->next; fast = fast->next->next; }. Loop B: the same but with condition (fast->next && fast->next->next). Where does slow stop in each case?", "options": ["A: 4, B: 4", "A: 4, B: 3", "A: 3, B: 3", "A: 3, B: 4"], "answer": 1, "explanation": "In A, fast goes 1 → 3 → 5 → past the end (null) while slow goes 1 → 2 → 3 → 4, the second middle. In B the loop stops when fast is at 5 (5.next.next is null), leaving slow at 3, the first middle. The difference matters for split-in-half algorithms.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-63","question":"What is the maximum number of comparisons top-down merge sort can make on 8 elements (any input order)?","options":["16","28","17","24"],"answer":2,"explanation":"In the worst case each merge of sizes m and n takes m + n − 1: 4 × 1 + 2 × 3 + 1 × 7 = 17 = n log₂ n − n + 1 = 24 − 8 + 1. 24 is the rough n log₂ n estimate, and checking all 8! inputs confirms 17.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-64","question":"What is the minimum number of comparisons needed, in the worst case, to find BOTH the maximum and the minimum of 100 distinct numbers?","options":["150","100","198","148"],"answer":3,"explanation":"Compare elements in pairs (50 comparisons), then find the max among the 50 winners (49) and the min among the 50 losers (49): 50 + 49 + 49 = 148 = ⌈3n/2⌉ − 2. Separate scans for max and min need 2(n − 1) = 198.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dsa-linear-65", "question": "One Lomuto partition (pivot = last element, i marks the end of the 'smaller' part, swap when a[j] < pivot) is applied to [7, 2, 9, 4, 3, 8, 6]. What is the array afterwards?", "options": ["2 4 3 6 9 8 7", "4 2 3 6 7 9 8", "2 4 3 6 7 8 9", "2 3 4 6 9 8 7"], "answer": 0, "explanation": "Elements smaller than 6 are swapped forward in the order met: 2 (swaps with 7), 4 (swaps with 9), 3 (swaps with 7), giving 2 4 3 7 9 8 6; finally the pivot swaps with a[3] = 7: 2 4 3 6 9 8 7. The right part is not sorted, and the left part keeps the order 4, 3.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-66", "question": "Insertion sort (ascending) is applied to [5, 2, 4, 6, 1, 3]. What does the array look like after the first 3 passes (i.e. after inserting the elements at indices 1, 2 and 3)?", "options": ["1 2 4 5 6 3", "2 4 5 6 1 3", "1 2 3 5 4 6", "2 4 5 1 6 3"], "answer": 1, "explanation": "Pass 1 inserts 2 → 2 5 4 6 1 3; pass 2 inserts 4 → 2 4 5 6 1 3; pass 3 inserts 6, which is already in place → 2 4 5 6 1 3. Only the prefix is sorted; 1 and 3 have not been touched yet. 1 2 4 5 6 3 is what you get after pass 4.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-67", "question": "Among insertion sort, merge sort, heap sort, quick sort, bubble sort and selection sort (standard array versions), how many are BOTH stable and in-place (O(1) extra space)?", "options": ["Four", "Three", "Two", "One"], "answer": 2, "explanation": "Insertion sort and bubble sort are both. Merge sort is stable but needs O(n) extra space; heap sort and quick sort are in-place but not stable; selection sort's long-distance swap breaks stability.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id":"cs-dsa-linear-68","question":"LSD radix sort (base 10, stable counting sort per digit) is applied to [170, 45, 75, 90, 802, 24, 2, 66]. What is the array after the FIRST pass (units digit)?","options":["2 24 45 66 75 90 170 802","170 90 2 802 24 45 75 66","802 2 24 45 66 170 75 90","170 90 802 2 24 45 75 66"],"answer":3,"explanation":"Group by units digit in the original order: 0 → 170, 90; 2 → 802, 2; 4 → 24; 5 → 45, 75; 6 → 66. Stability keeps 802 before 2 (and 170 before 90), so 2 802 is wrong; 802 2 24 … is the result after the second (tens) pass.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-69","question":"What does this function return for a = [1, 3, 3, 3, 5, 7] with x = 3 and with x = 4?\n```python\ndef g(a, x):\n    lo, hi = 0, len(a) - 1\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if a[mid] < x:\n            lo = mid + 1\n        else:\n            hi = mid\n    return lo\n```","options":["1 and 4","2 and 4","3 and 4","1 and 3"],"answer":0,"explanation":"This is a lower bound: it returns the first index whose value is ≥ x. The first 3 is at index 1, and the first value ≥ 4 is 5 at index 4. Thinking it returns 'mid when found' gives 2, the first midpoint.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-70","question":"while (lo <= hi) binary search runs on a sorted array of 31 elements for a key LARGER than every element. How many times does the loop body run?","options":["31","5","6","4"],"answer":1,"explanation":"The range shrinks 31 → 15 → 7 → 3 → 1 → 0, one iteration per halving while the range is non-empty: 5 iterations (log₂ 32 = 5). 4 forgets the last one-element check; 6 counts the failing loop test as an iteration.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-dsa-linear-71","question":"A dynamic array starts with capacity 1 and doubles its capacity (copying all current elements) whenever an insert finds it full. How many element copies happen in total while inserting 33 elements?","options":["33","64","63","32"],"answer":2,"explanation":"Resizes happen when inserting the 2nd, 3rd, 5th, 9th, 17th and 33rd elements, copying 1 + 2 + 4 + 8 + 16 + 32 = 63 elements, under 2n: O(1) amortised per insert. 32 counts only the last resize.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dsa-linear-72","question":"A stack-based checker is run on four strings. Which one is balanced?","options":["(()[]{}","{[}]()","([)]{}","{[()()]}[(())]"],"answer":3,"explanation":"In ([)]{} the ) arrives while [ is on top; {[}] has the same crossing; (()[]{} ends with one ( left on the stack. Only {[()()]}[(())] closes every bracket in reverse order of opening. Equal counts of each bracket type are not enough.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id":"cs-dsa-linear-73","question":"A circular queue in an array of size 6 uses front (index of the first item) and rear (index of the next free slot), both starting at 0, with one slot kept empty. After enqueuing a, b, c, d, e, dequeuing twice, then enqueuing f and g, what are rear and the queue state?","options":["rear = 1 and the queue is full","rear = 0 and the queue is full","rear = 7 and the queue is full","rear = 1 and one more item can be added"],"answer":0,"explanation":"After 5 enqueues rear = 5; two dequeues make front = 2; f goes to 5 (rear wraps to 0) and g to 0 (rear = 1). Now (rear + 1) mod 6 = 2 = front, so with one slot reserved the queue is full with 5 items. rear = 7 forgets the wrap-around.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-74","question":"A 2-D array A[10][20] (indices from 0) of 4-byte integers is stored in COLUMN-major order starting at address 1000. What is the address of A[5][7]?","options":["1328","1300","1428","1296"],"answer":1,"explanation":"In column-major order the 7 whole columns before it (10 elements each) come first, then 5 elements: offset = (7 × 10 + 5) × 4 = 300, so 1300. 1428 is the row-major answer, (5 × 20 + 7) × 4 + 1000.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dsa-linear-75","question":"Only the lower triangle (including the diagonal) of a 10 × 10 matrix is stored, row by row, in a 1-D array starting at address 2000, with 2 bytes per element and indices from 0. What is the address of element [6][4]?","options":["2048","2056","2050","2128"],"answer":2,"explanation":"Rows 0–5 hold 1 + 2 + … + 6 = 21 elements, then 4 more in row 6: offset 25 elements × 2 bytes = 50, so 2050. Using full rows (6 × 10 + 4 = 64 → 2128) ignores the triangular storage.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-76", "question": "What is printed? (Python)\n```python\na = [3, 8, 1, 9, 4]\na.insert(2, 7)\na.pop()\na.remove(9)\nprint(a, len(a))\n```", "options": ["[3, 8, 7, 1, 4] 5", "[3, 7, 8, 1] 4", "[3, 8, 7, 1] 4", "[3, 8, 1, 7] 4"], "answer": 2, "explanation": "insert(2, 7) puts 7 at index 2: [3, 8, 7, 1, 9, 4]; pop() removes the last element (4); remove(9) deletes the first 9 by value. Result [3, 8, 7, 1], length 4. insert and remove are O(n) because elements shift.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-77", "question": "A circular queue of size N = 5 keeps one slot empty. What is printed (dequeued values, 'F' for each rejected enqueue, final count)?\n```c\n#define N 5\nint q[N], front = 0, rear = 0;\nvoid enq(int x) { if ((rear + 1) % N == front) { printf(\"F\"); return; }\n                  q[rear] = x; rear = (rear + 1) % N; }\nint deq() { int x = q[front]; front = (front + 1) % N; return x; }\n/* enq 1..5; a = deq(); b = deq(); enq(6); enq(7); enq(8);\n   print a, b, the F's, and (rear - front + N) % N */\n```", "options": ["1 2 F 4", "1 2 FF 4", "1 2 FF 3", "1 2 F 5"], "answer": 1, "explanation": "With one slot kept empty the queue holds N − 1 = 4 items. Enqueuing 1..5 rejects 5 (first F). After two dequeues there are 2 items; 6 and 7 fit (4 items), and 8 is rejected (second F). The count (rear − front + N) % N is 4.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-78", "question": "Keys 50, 700, 76, 85, 92, 73, 101 are inserted into a hash table of size 7 with h(k) = k mod 7 and linear probing. What is the final table (slots 0–6)?\n```python\nm = 7; t = [None] * m\nfor k in (50, 700, 76, 85, 92, 73, 101):\n    i = k % m\n    while t[i] is not None: i = (i + 1) % m\n    t[i] = k\nprint(\" \".join(\"-\" if x is None else str(x) for x in t))\n```", "options": ["700 50 85 73 101 92 76", "700 50 92 85 73 101 76", "700 85 50 92 73 101 76", "700 50 85 92 73 101 76"], "answer": 3, "explanation": "Home slots: 50→1, 700→0, 76→6, 85→1 (taken) →2, 92→1 →2 →3, 73→3 →4, 101→3 →4 →5. Primary clustering makes later keys walk past the growing cluster at slots 0–5.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-79", "question": "Keys 22, 33, 44, 55 go into a table of size 11 with quadratic probing h(k) + i² (mod 11). In which slots do they land, in order?\n```python\nm = 11; t = [None] * m; slots = []\nfor k in (22, 33, 44, 55):\n    h = k % m; i = 0\n    while t[(h + i * i) % m] is not None: i += 1\n    t[(h + i * i) % m] = k; slots.append((h + i * i) % m)\nprint(*slots)\n```", "options": ["0 1 4 9", "0 1 2 3", "0 1 3 6", "0 2 4 6"], "answer": 0, "explanation": "All four keys hash to 0. Quadratic probing tries offsets 0, 1, 4, 9: 22 → 0, 33 → 1, 44 → 4, 55 → 9. Linear probing would give 0, 1, 2, 3. Keys with the same home slot still follow the same sequence (secondary clustering).", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-80", "question": "What is printed? (stack-based reversal of words)\n```python\ns = \"data structures are fun\"\nst = []\nfor w in s.split():\n    st.append(w)\nout = []\nwhile st:\n    out.append(st.pop()[::-1])\nprint(\" \".join(out))\n```", "options": ["fun are structures data", "nuf era serutcurts atad", "atad serutcurts era nuf", "nuf era structures data"], "answer": 1, "explanation": "Popping the stack reverses the word order (fun, are, structures, data), and [::-1] reverses each word's letters, so the whole string is reversed: \"nuf era serutcurts atad\".", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-81", "question": "Convert the infix expression to postfix (^ is right-associative, higher than * and /, which are higher than + and −). What is printed?\n```python\ndef to_post(e):\n    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}\n    out, st = [], []\n    for ch in e:\n        if ch.isalnum(): out.append(ch)\n        elif ch == '(': st.append(ch)\n        elif ch == ')':\n            while st[-1] != '(': out.append(st.pop())\n            st.pop()\n        else:\n            while st and st[-1] != '(' and (prec[st[-1]] > prec[ch] or (prec[st[-1]] == prec[ch] and ch != '^')):\n                out.append(st.pop())\n            st.append(ch)\n    while st: out.append(st.pop())\n    return ''.join(out)\nprint(to_post(\"a+b*(c^d^e-f)/g\"))\n```", "options": ["abcd^e^f-*g/+", "abcde^^f-g/*+", "abcde^^-f*g/+", "abcde^^f-*g/+"], "answer": 3, "explanation": "Inside the brackets, c^d^e groups as c^(d^e) → cde^^, then −f → cde^^f−. b*(…) then /g is left-associative: b(…)*g/. Finally a + … → a…+. Treating ^ as left-associative gives cd^e^.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-82", "question": "Evaluate the postfix expression with single-digit operands. What is printed?\n```python\nst = []\nfor t in \"62/3-42*+\":\n    if t.isdigit(): st.append(int(t))\n    else:\n        b, a = st.pop(), st.pop()\n        st.append({'+': a + b, '-': a - b, '*': a * b, '/': a // b}[t])\nprint(st)\n```", "options": ["[8]", "[2]", "[-8]", "[6]"], "answer": 0, "explanation": "6/2 = 3, 3 − 3 = 0, 4·2 = 8, 0 + 8 = 8. The second popped value is the left operand; popping the other way round gives 2/6 = 0 and different results.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-83", "question": "What is printed? (deque operations)\n```python\nfrom collections import deque\nd = deque([1, 2, 3])\nd.appendleft(0); d.append(4)\nd.rotate(2)\nd.popleft()\nprint(list(d), d[0])\n```", "options": ["[0, 1, 2, 3] 0", "[4, 0, 1, 2, 3] 4", "[4, 0, 1, 2] 4", "[1, 2, 3, 4] 1"], "answer": 2, "explanation": "After appendleft and append: [0, 1, 2, 3, 4]. rotate(2) moves the last two elements to the front: [3, 4, 0, 1, 2]. popleft removes 3, leaving [4, 0, 1, 2] with 4 at the front. All these deque operations are O(1) (rotate is O(k)), unlike list.insert(0, x).", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-84", "question": "What is printed? (singly linked list, delete every node whose value equals x)\n```python\nclass N:\n    def __init__(s, v, n=None): s.v, s.n = v, n\nh = N(2, N(2, N(5, N(2, N(7, N(2))))))\ndef remove_all(h, x):\n    d = N(0, h); p = d\n    while p.n:\n        if p.n.v == x: p.n = p.n.n\n        else: p = p.n\n    return d.n\nr = remove_all(h, 2); out = []\nwhile r: out.append(r.v); r = r.n\nprint(out)\n```", "options": ["[2, 5, 7]", "[5, 7, 2]", "[5, 2, 7]", "[5, 7]"], "answer": 3, "explanation": "A dummy head handles deleting the first nodes uniformly. When the next node matches, p stays put so consecutive matches are all removed; it advances only past a kept node. Without the dummy the leading 2s need special-case code. O(n), O(1) extra space.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-85", "question": "What is printed? (finding the intersection node of two linked lists by switching heads)\n```python\nclass N:\n    def __init__(s, v, n=None): s.v, s.n = v, n\ncommon = N(8, N(4, N(5)))\na = N(4, N(1, common))\nb = N(5, N(6, N(1, common)))\np, q, steps = a, b, 0\nwhile p is not q:\n    p = p.n if p else b\n    q = q.n if q else a\n    steps += 1\nprint(p.v, steps)\n```", "options": ["8 9", "1 9", "8 5", "8 11"], "answer": 0, "explanation": "Each pointer walks its own list, takes one step onto None, then restarts at the head of the other list, so both cover the same distance before meeting at the first shared node: (5 + 1) + 3 = 9 steps for p and (6 + 1) + 2 = 9 for q. They meet at the node with value 8 – the two nodes with value 1 are different objects, which is why identity (is), not ==, is compared. O(m + n), O(1) space.", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-86", "question": "What is printed? (Java String vs StringBuilder)\n```java\nString s = \"ab\";\ns.concat(\"cd\");\nStringBuilder sb = new StringBuilder(\"ab\");\nsb.append(\"cd\");\nSystem.out.println(s + \" \" + sb + \" \" + s.length() + sb.length());\n```", "options": ["abcd abcd 44", "ab abcd 24", "ab abcd 6", "abcd abcd 8"], "answer": 1, "explanation": "Strings are immutable: s.concat(\"cd\") returns a new string that is discarded, so s stays \"ab\". StringBuilder.append mutates in place. In the + chain, s.length() + sb.length() are joined as strings after the preceding string, giving \"2\" then \"4\" → \"24\", not 6.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-87", "question": "What is printed? (counting sort on small values)\n```python\na = [4, 1, 3, 4, 2, 1, 0, 4]\ncnt = [0] * 5\nfor x in a: cnt[x] += 1\nfor i in range(1, 5): cnt[i] += cnt[i - 1]\nprint(cnt, cnt[4] - cnt[3])\n```", "options": ["[1, 2, 1, 1, 3] 3", "[1, 3, 4, 5, 8] 2", "[1, 3, 4, 5, 8] 3", "[0, 1, 3, 4, 5] 3"], "answer": 2, "explanation": "Raw counts are 1, 2, 1, 1, 3; the prefix sums give the end position of each value's block in the output: [1, 3, 4, 5, 8]. cnt[4] − cnt[3] recovers the number of 4s (3). Counting sort is O(n + k) and stable when filled from the right.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-88", "question": "How many swaps does this bubble sort make, and how many passes run?\n```python\na = [5, 1, 4, 2, 8]\nswaps = passes = 0\nfor i in range(len(a) - 1):\n    passes += 1; swapped = False\n    for j in range(len(a) - 1 - i):\n        if a[j] > a[j + 1]:\n            a[j], a[j + 1] = a[j + 1], a[j]; swaps += 1; swapped = True\n    if not swapped: break\nprint(swaps, passes)\n```", "options": ["4 4", "3 3", "4 3", "5 3"], "answer": 2, "explanation": "Bubble sort swaps exactly once per inversion: (5,1), (5,4), (5,2), (4,2) → 4 swaps. Pass 1 gives [1, 4, 2, 5, 8], pass 2 [1, 2, 4, 5, 8], pass 3 makes no swap and stops early. Without the flag all 4 passes run.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-89", "question": "Insertion sort counts element shifts. What is printed?\n```python\na = [3, 7, 1, 5, 2]\nshifts = 0\nfor i in range(1, len(a)):\n    key, j = a[i], i - 1\n    while j >= 0 and a[j] > key:\n        a[j + 1] = a[j]; j -= 1; shifts += 1\n    a[j + 1] = key\nprint(a, shifts)\n```", "options": ["[1, 2, 3, 5, 7] 5", "[1, 2, 3, 5, 7] 6", "[1, 2, 3, 5, 7] 7", "[1, 2, 3, 5, 7] 4"], "answer": 1, "explanation": "The number of shifts equals the number of inversions: (3,1), (3,2), (7,1), (7,5), (7,2), (5,2) = 6. On sorted input insertion sort makes 0 shifts (O(n)); on reversed input n(n−1)/2.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-90", "question": "Quick sort with Lomuto partition (last element as pivot). What is the array after the FIRST partition, and the pivot's final index?\n```python\na = [7, 2, 9, 4, 3, 8, 5]\np = a[-1]; i = -1\nfor j in range(len(a) - 1):\n    if a[j] <= p:\n        i += 1; a[i], a[j] = a[j], a[i]\na[i + 1], a[-1] = a[-1], a[i + 1]\nprint(a, i + 1)\n```", "options": ["[2, 4, 3, 5, 7, 9, 8] 3", "[2, 3, 4, 5, 9, 8, 7] 3", "[4, 2, 3, 5, 9, 8, 7] 3", "[2, 4, 3, 5, 9, 8, 7] 3"], "answer": 3, "explanation": "Elements ≤ 5 (2, 4, 3) are swapped to the front in order of appearance; then the pivot swaps with the first larger element (7) at index 3. The right side [9, 8, 7] is not sorted yet. On already-sorted input Lomuto degrades to O(n²).", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-91", "question": "Merge two sorted halves and count comparisons. What is printed?\n```python\nL, R = [1, 4, 6, 9], [2, 3, 10]\ni = j = comps = 0; out = []\nwhile i < len(L) and j < len(R):\n    comps += 1\n    if L[i] <= R[j]: out.append(L[i]); i += 1\n    else: out.append(R[j]); j += 1\nout += L[i:] + R[j:]\nprint(comps, out[-2:])\n```", "options": ["6 [9, 10]", "7 [9, 10]", "5 [9, 10]", "6 [6, 9]"], "answer": 0, "explanation": "Comparisons: 1–2, 4–2, 4–3, 4–10, 6–10, 9–10; then L is exhausted and 10 is copied without comparing. That is 6 = m + n − 1, the worst case, because the lists interleave until the very end. The tail gives [9, 10]. Merging is O(m + n).", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-92", "question": "What is printed? (Python list aliasing)\n```python\na = [1, 2, 3]\nb = a\nc = a[:]\nb.append(4)\nc.append(5)\nprint(a, len(b), len(c))\n```", "options": ["[1, 2, 3, 4, 5] 5 4", "[1, 2, 3, 4] 4 4", "[1, 2, 3] 4 4", "[1, 2, 3, 4] 4 3"], "answer": 1, "explanation": "b = a makes b another name for the same list, so appending 4 through b changes a. a[:] is a shallow copy, so appending 5 to c leaves a alone. Both b and c end with 4 elements.", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-93", "question": "What is printed? (frequency of the most common character, ties to the earliest)\n```python\ns = \"programming\"\nbest = max(s, key=s.count)\nprint(best, s.count(best), len(set(s)))\n```", "options": ["r 2 8", "g 2 8", "m 2 8", "r 2 11"], "answer": 0, "explanation": "r, g and m each appear twice; max returns the FIRST element with the maximum key, which is 'r' (index 1). The string has 8 distinct letters (p, r, o, g, a, m, i, n). Note s.count inside max makes this O(n²); a Counter is O(n).", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-94", "question": "Sliding window: what is printed? (maximum sum of any 3 consecutive elements)\n```c\nint a[] = {4, -1, 6, -2, 3, 5, -4, 2};\nint n = 8, k = 3, s = 0, best;\nfor (int i = 0; i < k; i++) s += a[i];\nbest = s;\nfor (int i = k; i < n; i++) {\n    s += a[i] - a[i - k];\n    if (s > best) best = s;\n}\nprintf(\"%d\", best);\n```", "options": ["8", "7", "11", "9"], "answer": 3, "explanation": "Window sums: 9 (4−1+6), 3, 7, 6, 4, 3. The first window is already the best: 9. Each slide adds the new element and removes the one leaving – O(n) instead of O(nk).", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-95", "question": "What is printed? (two-pointer: remove all occurrences of a value in place)\n```cpp\nvector<int> a = {3, 2, 2, 3, 4, 3, 5};\nint w = 0;\nfor (int r = 0; r < a.size(); r++)\n    if (a[r] != 3) a[w++] = a[r];\ncout << w << \" \" << a[0] << a[1] << a[2] << a[3] << \" \" << a[4] << a[5] << a[6];\n```", "options": ["4 2245 345", "3 2245 435", "4 2245 435", "4 2245 000"], "answer": 2, "explanation": "The write pointer w copies only the kept values: 2, 2, 4, 5 → length 4. The slots after w are NOT cleared – they still hold the old values 4, 3, 5 from positions 4..6. Callers must use only the first w elements. O(n), O(1).", "difficulty": "moderate", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-96", "question": "What is printed? (stack: check if a sequence of pops is possible after pushing 1..n in order)\n```python\ndef valid(pushed, popped):\n    st, j = [], 0\n    for x in pushed:\n        st.append(x)\n        while st and j < len(popped) and st[-1] == popped[j]:\n            st.pop(); j += 1\n    return j == len(popped)\np = [1, 2, 3, 4, 5]\nprint(valid(p, [4, 5, 3, 2, 1]), valid(p, [4, 3, 5, 1, 2]), valid(p, [3, 2, 1, 5, 4]))\n```", "options": ["True True True", "False False True", "True False True", "True False False"], "answer": 2, "explanation": "Simulate: push in order and pop greedily whenever the top matches the next expected value. In [4, 3, 5, 1, 2], after popping 4, 3, 5 the stack is [1, 2] with 2 on top, so 1 cannot come next. O(n).", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-97", "question": "What is printed? (next greater element to the right, −1 if none)\n```python\na = [4, 5, 2, 25, 7, 8]\nres, st = [-1] * len(a), []\nfor i in range(len(a) - 1, -1, -1):\n    while st and st[-1] <= a[i]: st.pop()\n    res[i] = st[-1] if st else -1\n    st.append(a[i])\nprint(res)\n```", "options": ["[5, 25, 25, -1, 8, -1]", "[5, 25, 25, -1, 8, 8]", "[5, 25, 7, -1, 8, -1]", "[5, 5, 25, -1, 8, -1]"], "answer": 0, "explanation": "Scanning from the right, the stack keeps candidates in decreasing order; smaller or equal values are popped because they can never be the answer for anything further left. 2's next greater is 25 (not 7, which is further right). O(n).", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-98", "question": "Hash map counting: what is printed? (first element that repeats, scanning left to right)\n```python\ndef first_repeat(a):\n    seen = set()\n    for x in a:\n        if x in seen: return x\n        seen.add(x)\n    return None\ndef first_with_dup(a):\n    from collections import Counter\n    c = Counter(a)\n    return next((x for x in a if c[x] > 1), None)\na = [10, 5, 3, 4, 3, 5, 6]\nprint(first_repeat(a), first_with_dup(a))\n```", "options": ["5 3", "3 5", "3 3", "5 5"], "answer": 1, "explanation": "These answer different questions. first_repeat returns the first value whose SECOND occurrence comes earliest (3 repeats at index 4 before 5 repeats at index 5). first_with_dup returns the earliest element that has any duplicate: 5 (index 1). Both O(n).", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-99", "question": "What is printed? (anagram check two ways)\n```python\nfrom collections import Counter\nx, y = \"listen\", \"enlists\"\nprint(sorted(x) == sorted(y), Counter(x) == Counter(y), set(x) == set(y))\n```", "options": ["True True True", "False True True", "False False False", "False False True"], "answer": 3, "explanation": "\"enlists\" has an extra 's', so sorted letters and counts differ – not anagrams. A set comparison ignores multiplicity and wrongly says True. Sorting is O(n log n); counting is O(n).", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-100", "question": "Binary search: how many iterations does this loop run to find x = 23?\n```python\na = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]\nlo, hi, it = 0, len(a) - 1, 0\nwhile lo <= hi:\n    it += 1\n    mid = (lo + hi) // 2\n    if a[mid] == 23: break\n    if a[mid] < 23: lo = mid + 1\n    else: hi = mid - 1\nprint(it, mid)\n```", "options": ["3 5", "2 5", "1 5", "4 5"], "answer": 0, "explanation": "First mid = 4 (16 < 23) → lo = 5; second mid = (5 + 9)//2 = 7 (56 > 23) → hi = 6; third mid = (5 + 6)//2 = 5 → found. 3 iterations, within the ⌊log₂ 10⌋ + 1 = 4 worst case. Linear search would need 6 comparisons.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-101", "question": "What is printed? (run-length decode then re-encode)\n```python\nimport re\nenc = \"a3b1c12\"\ndec = \"\".join(ch * int(n) for ch, n in re.findall(r\"([a-z])(\\d+)\", enc))\nprint(len(dec), dec[3:6])\n```", "options": ["7 bcc", "16 bc1", "6 bcc", "16 bcc"], "answer": 3, "explanation": "The pattern pairs each letter with its full (possibly multi-digit) count: a×3, b×1, c×12 → length 16; indices 3..5 are 'b', 'c', 'c'. Reading only one digit per letter would treat '12' as 1 and break the decoding. O(output length).", "difficulty": "moderate", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-102", "question": "What is printed? (move zeros to the end keeping order)\n```python\na = [0, 1, 0, 3, 12, 0, 5]\nw = 0\nfor r in range(len(a)):\n    if a[r] != 0:\n        a[w], a[r] = a[r], a[w]\n        w += 1\nprint(a, w)\n```", "options": ["[1, 3, 12, 5, 0, 0, 0] 3", "[1, 3, 12, 5, 0, 0, 0] 4", "[1, 3, 5, 12, 0, 0, 0] 4", "[5, 12, 3, 1, 0, 0, 0] 4"], "answer": 1, "explanation": "Swapping each non-zero into the write position keeps the relative order of the non-zeros and pushes zeros back. w ends at the number of non-zeros (4). O(n), O(1) extra space, one pass.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-103", "question": "What is the time complexity of deleting the last node of a singly linked list of n nodes when only a head pointer is kept?", "options": ["O(1) – the tail is reachable directly", "O(log n)", "O(n²)", "O(n) – the second-last node must be found to update its next pointer"], "answer": 3, "explanation": "Even if a tail pointer existed, removing the tail requires its predecessor, which a singly linked list can only reach by walking from the head. A doubly linked list with a tail pointer makes this O(1).", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-104", "question": "A stack is implemented with a singly linked list. Where should push and pop operate to keep both O(1)?", "options": ["At the tail – append and remove the tail", "Push at the head, pop at the tail", "At the head – insert a new head and remove the head", "Push at the tail, pop at the head"], "answer": 2, "explanation": "Head insertion and head deletion are both pointer updates. Removing the tail needs the predecessor (O(n)), so any design that pops at the tail is O(n). Push at tail/pop at head is a queue, not a stack.", "difficulty": "easy", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-105", "question": "What is printed? (C strings)\n```c\nchar s[] = \"Placement\";\nprintf(\"%zu %zu\", strlen(s), sizeof(s));\n```", "options": ["9 10", "9 9", "10 10", "9 8"], "answer": 0, "explanation": "strlen counts characters before the terminating '\\0': 9. sizeof on a char array includes the terminator, so the array occupies 10 bytes. For a char * pointer, sizeof would give the pointer size instead.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-106", "question": "What is printed? (pointer arithmetic on an int array)\n```c\nint a[] = {10, 20, 30, 40, 50};\nint *p = a + 1;\nprintf(\"%d \", *(p + 2));\nprintf(\"%d \", *p++ + 2);\nprintf(\"%d\", *p);\n```", "options": ["40 32 30", "40 22 30", "30 22 30", "40 22 20"], "answer": 1, "explanation": "p points to a[1] = 20. *(p + 2) is a[3] = 40. *p++ + 2 reads *p (20) then advances p, so it prints 22, and p now points to a[2] = 30. Postfix ++ binds tighter than *, but the dereference uses the old pointer value.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-107", "question": "What is printed? (2-D array in row-major order)\n```python\nR, C = 3, 4\nbase, size = 1000, 4\ndef addr(i, j, row_major=True):\n    return base + size * (i * C + j if row_major else j * R + i)\nprint(addr(2, 1), addr(2, 1, False))\n```", "options": ["1036 1020", "1036 1028", "1020 1036", "1024 1020"], "answer": 0, "explanation": "Row-major: offset = i·C + j = 2·4 + 1 = 9 elements → 1000 + 36. Column-major: offset = j·R + i = 1·3 + 2 = 5 → 1000 + 20. C and Python (NumPy default) are row-major; Fortran is column-major.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-108", "question": "What is printed? (Python string immutability and methods)\n```python\ns = \"Hello World\"\nt = s.replace(\"o\", \"0\", 1)\nu = s.swapcase()[::2]\nprint(s, t, u)\n```", "options": ["Hell0 World Hell0 World hLOwRD", "Hello World Hell0 W0rld hLOwRD", "Hello World Hell0 World hLOwRD", "Hello World Hell0 World hLO RD"], "answer": 2, "explanation": "Strings are immutable, so s is unchanged. replace(..., 1) replaces only the first 'o'. swapcase gives \"hELLO wORLD\" and [::2] takes indices 0, 2, 4, …: h, L, O, w, R, D.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-109", "question": "What is printed? (queue simulation – hot potato with step k)\n```python\nfrom collections import deque\nq = deque(range(1, 8)); out = []\nwhile len(q) > 1:\n    q.rotate(-2)\n    out.append(q.popleft())\nprint(out, q[0])\n```", "options": ["[3, 6, 2, 7, 5, 1] 3", "[2, 4, 6, 1, 5, 3] 7", "[3, 6, 1, 5, 2, 7] 4", "[3, 6, 2, 7, 5, 1] 4"], "answer": 3, "explanation": "Each round passes the potato twice (rotate left by 2) and eliminates the person now at the front – the Josephus problem with every 3rd person removed. For n = 7, k = 3 the survivor is 4. The deque gives O(k) per elimination.", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-110", "question": "What is printed? (Josephus recurrence)\n```python\ndef josephus(n, k):\n    r = 0\n    for m in range(2, n + 1):\n        r = (r + k) % m\n    return r + 1\nprint(josephus(7, 3), josephus(10, 2), josephus(1, 5))\n```", "options": ["4 4 1", "4 5 1", "3 5 1", "4 5 0"], "answer": 1, "explanation": "J(1) = 0 and J(m) = (J(m − 1) + k) mod m (0-based); add 1 for 1-based positions. n = 7, k = 3 → 4; n = 10, k = 2 → 5 (also 2·(10 − 8) + 1). O(n) instead of simulating the circle in O(nk).", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-111", "question": "What is printed? (hash set for pairs with a given difference)\n```python\ndef pairs_diff(a, k):\n    s = set(a)\n    return sorted((x, x + k) for x in s if x + k in s)\nprint(pairs_diff([1, 7, 5, 9, 2, 12, 3], 2), len(pairs_diff([1, 1, 1, 2], 0)))\n```", "options": ["[(1, 3), (3, 5), (5, 7), (7, 9)] 1", "[(1, 3), (5, 7), (7, 9)] 2", "[(1, 3), (3, 5), (5, 7), (7, 9), (10, 12)] 2", "[(1, 3), (3, 5), (5, 7), (7, 9)] 2"], "answer": 3, "explanation": "With k = 2 the distinct pairs are (1,3), (3,5), (5,7), (7,9); 12 − 2 = 10 is absent. For k = 0 the set version is wrong: every distinct value pairs with itself, giving (1,1) and (2,2) = 2, although only 1 has a real duplicate (answer 1). k = 0 needs a count map (values seen at least twice). O(n).", "difficulty": "moderate", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-112", "question": "What is printed? (Python dict ordering and update)\n```python\nd = {\"b\": 1, \"a\": 2}\nd[\"c\"] = 3\nd[\"b\"] = 4\ndel d[\"a\"]\nd[\"a\"] = 5\nprint(list(d.items()))\n```", "options": ["[('a', 5), ('b', 4), ('c', 3)]", "[('b', 4), ('c', 3), ('a', 5)]", "[('b', 4), ('a', 5), ('c', 3)]", "[('c', 3), ('b', 4), ('a', 5)]"], "answer": 1, "explanation": "Since Python 3.7 dicts keep insertion order. Updating an existing key ('b') keeps its position; deleting 'a' and inserting it again puts it at the end. Lookups stay O(1) average.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-113", "question": "What is printed? (prefix sums for range queries)\n```python\na = [3, -2, 5, 1, -4, 6]\nP = [0]\nfor x in a: P.append(P[-1] + x)\nq = [(0, 2), (1, 4), (3, 5), (5, 5)]\nprint([P[r + 1] - P[l] for l, r in q])\n```", "options": ["[6, 0, 3, 0]", "[1, 0, 3, 6]", "[6, 0, 3, 6]", "[6, -4, 3, 6]"], "answer": 2, "explanation": "P = [0, 3, 1, 6, 7, 3, 9]. Sum a[l..r] = P[r + 1] − P[l]: (0,2) → 6, (1,4) → 3 − 3 = 0, (3,5) → 9 − 6 = 3, (5,5) → 9 − 3 = 6. Using P[r] − P[l] drops the last element. O(1) per query after O(n) setup.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-114", "question": "What is printed? (difference array for range increments)\n```python\nn = 6\ndiff = [0] * (n + 1)\nfor l, r, v in [(0, 2, 5), (1, 4, 3), (3, 5, -2)]:\n    diff[l] += v; diff[r + 1] -= v\na, run = [], 0\nfor i in range(n):\n    run += diff[i]; a.append(run)\nprint(a)\n```", "options": ["[5, 8, 8, 1, 1, -2]", "[5, 8, 8, 3, 3, -2]", "[5, 8, 8, 1, 1, 0]", "[5, 3, 0, -2, 0, 2]"], "answer": 0, "explanation": "Each range update touches two cells of the difference array; a final prefix sum rebuilds the values. Index 3: +3 − 2 = 1; index 5: −2 only. O(1) per update and O(n) to rebuild, instead of O(length) per update.", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-115", "question": "What is printed? (Python sort stability with a key)\n```python\nrecs = [(\"amit\", 82), (\"bina\", 90), (\"chirag\", 82), (\"dev\", 75), (\"esha\", 90)]\nby_score = sorted(recs, key=lambda r: -r[1])\nprint([n for n, _ in by_score])\n```", "options": ["['bina', 'esha', 'amit', 'chirag', 'dev']", "['esha', 'bina', 'chirag', 'amit', 'dev']", "['bina', 'esha', 'chirag', 'amit', 'dev']", "['dev', 'amit', 'chirag', 'bina', 'esha']"], "answer": 0, "explanation": "Python's Timsort is stable, so records with equal scores keep their original order: bina before esha, amit before chirag. Sorting with reverse=True would also keep ties in original order. O(n log n).", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-116", "question": "What is printed? (finding the k-th node from the end with two pointers)\n```python\nvals = [11, 22, 33, 44, 55, 66]\ndef kth_end(k):\n    lead = trail = 0\n    for _ in range(k):\n        if lead == len(vals): return None\n        lead += 1\n    while lead < len(vals): lead += 1; trail += 1\n    return vals[trail]\nprint(kth_end(1), kth_end(4), kth_end(6), kth_end(7))\n```", "options": ["66 44 11 None", "66 33 11 None", "55 33 11 None", "66 33 11 66"], "answer": 1, "explanation": "Advance the leader k steps, then move both until the leader falls off; the trailer is then k from the end. k = 4 → 33; k = 6 → the first element; k = 7 exceeds the length → None. One pass, O(n).", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-117", "question": "What is printed? (C: array passed to a function decays to a pointer)\n```c\nvoid f(int a[]) { printf(\"%zu \", sizeof(a) / sizeof(a[0])); }\nint main(void) {\n    int a[10];\n    printf(\"%zu \", sizeof(a) / sizeof(a[0]));\n    f(a);\n    return 0;\n}   /* 64-bit system: 8-byte pointers, 4-byte int */\n```", "options": ["10 10", "10 1", "40 8", "10 2"], "answer": 3, "explanation": "In main, a is an array of 10 ints: 40 / 4 = 10. A parameter declared int a[] is really int *a, so inside f sizeof(a) is the pointer size 8, giving 8 / 4 = 2. Pass the length separately – the classic array-length bug.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-118", "question": "What is printed? (balanced brackets with a counter only)\n```python\ndef by_counter(s):\n    c = 0\n    for ch in s:\n        c += 1 if ch == '(' else -1\n        if c < 0: return False\n    return c == 0\nprint(by_counter(\"(()())\"), by_counter(\"())(()\"), by_counter(\")(\"))\n```", "options": ["True True False", "True False True", "True False False", "False False False"], "answer": 2, "explanation": "With a single bracket type a counter suffices: it must never go negative and must end at 0. \"())(()\" dips to −1 after the third character. With several bracket types a stack is required, because \"([)]\" has balanced counts but wrong nesting.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-119", "question": "What is printed? (string rotation check)\n```python\ndef is_rot(a, b):\n    return len(a) == len(b) and b in a + a\nprint(is_rot(\"waterbottle\", \"erbottlewat\"), is_rot(\"abcd\", \"acbd\"), is_rot(\"\", \"\"))\n```", "options": ["True True True", "True False True", "True False False", "False False True"], "answer": 1, "explanation": "Every rotation of a appears as a substring of a + a. \"acbd\" is a permutation but not a rotation. Two empty strings are trivially rotations. With KMP the containment check is O(n).", "difficulty": "moderate", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-120", "question": "What is printed? (sliding window: count subarrays with product less than k, positive values)\n```python\ndef count_prod(a, k):\n    if k <= 1: return 0\n    prod = 1; l = res = 0\n    for r, x in enumerate(a):\n        prod *= x\n        while prod >= k:\n            prod //= a[l]; l += 1\n        res += r - l + 1\n    return res\nprint(count_prod([10, 5, 2, 6], 100), count_prod([1, 2, 3], 0))\n```", "options": ["8 0", "7 0", "8 6", "6 0"], "answer": 0, "explanation": "For each right end, every window [l..r] whose product is below k counts: 1 + 2 + 2 + 3 = 8 ([10], [10,5], [5], [5,2], [2], [5,2,6], [2,6], [6]). k ≤ 1 can never be beaten by positive integers, and the early return avoids an empty-window infinite loop. O(n).", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-121", "question": "What is printed? (Java: == vs equals on Strings)\n```java\nString a = \"hello\";\nString b = \"hel\" + \"lo\";\nString c = new String(\"hello\");\nString d = c.intern();\nSystem.out.println((a == b) + \" \" + (a == c) + \" \" + a.equals(c) + \" \" + (a == d));\n```", "options": ["true true true true", "false false true true", "true false true true", "true false true false"], "answer": 2, "explanation": "\"hel\" + \"lo\" is a compile-time constant, so it refers to the same pooled literal as a. new String creates a distinct object (== false, equals true). intern() returns the pooled instance, so a == d. Always compare contents with equals.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-122", "question": "What is printed? (expected probes in a hash table)\n```python\nalpha = 0.75\nchaining = 1 + alpha / 2\nlinear_hit = 0.5 * (1 + 1 / (1 - alpha))\nlinear_miss = 0.5 * (1 + 1 / (1 - alpha) ** 2)\nprint(round(chaining, 3), linear_hit, linear_miss)\n```", "options": ["1.75 2.5 8.5", "1.375 4.0 16.0", "1.375 2.5 4.5", "1.375 2.5 8.5"], "answer": 3, "explanation": "Standard estimates (Knuth): successful search with chaining ≈ 1 + α/2; with linear probing ≈ ½(1 + 1/(1 − α)) for hits and ½(1 + 1/(1 − α)²) for misses. At α = 0.75 a miss already costs about 8.5 probes, which is why open-addressing tables resize around α ≈ 0.5–0.75.", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-123", "question": "What is printed? (reverse a sublist of a linked list between positions m and n, 1-based)\n```python\ndef rev_between(a, m, n):\n    a = a[:]\n    a[m - 1:n] = a[m - 1:n][::-1]\n    return a\nprint(rev_between([1, 2, 3, 4, 5, 6], 2, 5), rev_between([7, 8], 1, 2))\n```", "options": ["[1, 5, 4, 3, 2, 6] [8, 7]", "[1, 4, 3, 2, 5, 6] [8, 7]", "[1, 5, 4, 3, 2, 6] [7, 8]", "[5, 4, 3, 2, 1, 6] [8, 7]"], "answer": 0, "explanation": "Positions 2..5 (values 2, 3, 4, 5) are reversed in place, the rest untouched. In a real linked list this is done in one pass with a dummy head: find node m − 1, then repeatedly move the next node to the front of the sublist – O(n), O(1) space.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-124", "question": "What is printed? (min-heap array after inserts)\n```python\nimport heapq\nh = []\nfor x in [9, 4, 7, 1, 8, 2]:\n    heapq.heappush(h, x)\nprint(h, heapq.heappop(h), h)\n```", "options": ["[1, 4, 2, 9, 8, 7] 1 [2, 4, 7, 9, 8]", "[1, 2, 4, 7, 8, 9] 1 [2, 4, 7, 8, 9]", "[2, 4, 7, 8, 9] 1 [2, 4, 7, 8, 9]", "[2, 4, 7, 9, 8] 1 [2, 4, 7, 9, 8]"], "answer": 3, "explanation": "After the six pushes the heap array is [1, 4, 2, 9, 8, 7] (a heap, not a sorted list). But print's arguments are all evaluated before anything is printed, and both h arguments are the same list object – heappop has already moved 7 to the root and sifted it below 2, so both show [2, 4, 7, 9, 8]. Push and pop are O(log n).", "difficulty": "hard", "source": "Product Company SDE pattern"},
  {"id": "cs-dsa-linear-125", "question": "What is printed? (queue using a fixed array without wrap-around)\n```python\nN = 4; q = [None] * N; front = rear = 0; log = []\ndef enq(x):\n    global rear\n    if rear == N: log.append(\"full\"); return\n    q[rear] = x; rear += 1\ndef deq():\n    global front\n    x = q[front]; front += 1; return x\nfor x in (1, 2, 3, 4): enq(x)\ndeq(); deq()\nenq(5)\nprint(log, rear - front)\n```", "options": ["[] 3", "['full'] 3", "['full'] 2", "[] 2"], "answer": 2, "explanation": "A linear array queue never reuses the slots freed at the front: after two dequeues there are only 2 items, yet rear == N, so enqueue 5 is rejected ('false overflow'). A circular queue with (rear + 1) % N fixes this.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-dsa-linear-126", "question": "A warehouse scores a shelf by adding, over every contiguous run of boxes, the weight of the lightest box in the run. Two monotonic-stack versions differ only in how the right-hand scan treats EQUAL weights. What is printed?\n```python\ndef score(a, strict_right):\n    n = len(a); left = [0] * n; right = [0] * n; st = []\n    for i in range(n):\n        while st and a[st[-1]] > a[i]: st.pop()\n        left[i] = i - (st[-1] if st else -1); st.append(i)\n    st = []\n    for i in range(n - 1, -1, -1):\n        while st and (a[st[-1]] > a[i] if strict_right else a[st[-1]] >= a[i]): st.pop()\n        right[i] = (st[-1] if st else n) - i; st.append(i)\n    return sum(a[i] * left[i] * right[i] for i in range(n))\na = [3, 1, 2, 1, 4]\nprint(score(a, False), score(a, True))\n```", "options": ["21 17", "21 21", "19 21", "21 25"], "answer": 0, "explanation": "a[i] contributes a[i] × left[i] × right[i], where the two spans count the subarrays in which a[i] is 'the' minimum. With duplicates, exactly one side may cross equal values. The left scan stops at the previous element ≤ a[i]; version 1's right scan pops ≥ and so stops only at a strictly smaller one – each subarray is credited to its leftmost… rightmost minimum exactly once, giving the true total 21 (brute force over the 15 subarrays agrees). Version 2 makes BOTH sides stop at an equal value, so a subarray containing both 1s is credited to neither: the 4 such subarrays are lost, 21 − 4 = 17. Making both sides cross equals would overcount instead.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-127", "question": "A monotonic deque reports the maximum of every window of 3 readings and counts deque removals. What is printed?\n```python\nfrom collections import deque\ndef win_max(a, k):\n    dq, out, pops = deque(), [], 0\n    for i, x in enumerate(a):\n        while dq and a[dq[-1]] <= x: dq.pop(); pops += 1\n        dq.append(i)\n        if dq[0] <= i - k: dq.popleft(); pops += 1\n        if i >= k - 1: out.append(a[dq[0]])\n    return out, pops\nprint(*win_max([5, 1, 3, 2, 6, 2, 2, 4, 1], 3))\n```", "options": ["[5, 3, 6, 6, 6, 4, 4] 9", "[5, 3, 6, 6, 6, 4, 4] 7", "[5, 3, 6, 6, 6, 6, 4] 7", "[5, 5, 6, 6, 6, 4, 4] 7"], "answer": 1, "explanation": "The deque holds indices with strictly decreasing values; a new reading evicts every smaller-or-equal one from the back, and the front is dropped once it falls out of the window. Windows: [5,1,3]→5, [1,3,2]→3, [3,2,6]→6, [2,6,2]→6, [6,2,2]→6, [2,2,4]→4, [2,4,1]→4. Each index enters once and leaves at most once, so total removals ≤ n; here 7 (5 back pops + 2 front expiries), which is why the whole pass is O(n) even though the inner while looks quadratic.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-128", "question": "at_most(s, k) counts substrings with at most k distinct letters using a sliding window and a frequency map. What is printed?\n```python\ndef at_most(s, k):\n    cnt, lo, total = {}, 0, 0\n    for hi, ch in enumerate(s):\n        cnt[ch] = cnt.get(ch, 0) + 1\n        while len(cnt) > k:\n            cnt[s[lo]] -= 1\n            if cnt[s[lo]] == 0: del cnt[s[lo]]\n            lo += 1\n        total += hi - lo + 1\n    return total\ns = \"abcabba\"\nprint(at_most(s, 2), at_most(s, 1), at_most(s, 2) - at_most(s, 1))\n```", "options": ["16 7 9", "13 8 5", "16 8 8", "28 8 20"], "answer": 2, "explanation": "For each right end hi the window [lo, hi] is the longest valid one ending at hi, and every shorter suffix of it is valid too, so it contributes hi − lo + 1 substrings. at_most(2) = 1+2+2+2+2+3+4 = 16 and at_most(1) = 1+1+1+1+1+2+1 = 8 (the runs 'bb' add an extra). 'Exactly k distinct' is not monotone under shrinking, so it is computed as at_most(k) − at_most(k − 1) = 8. 28 is the total number of substrings.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-129", "question": "A KMP prefix (failure) table and an overlapping-occurrence counter. What is printed?\n```python\ndef prefix(p):\n    pi = [0] * len(p)\n    for i in range(1, len(p)):\n        k = pi[i - 1]\n        while k and p[i] != p[k]: k = pi[k - 1]\n        if p[i] == p[k]: k += 1\n        pi[i] = k\n    return pi\ndef count(t, p):\n    pi, k, c = prefix(p), 0, 0\n    for ch in t:\n        while k and ch != p[k]: k = pi[k - 1]\n        if ch == p[k]: k += 1\n        if k == len(p): c += 1; k = pi[k - 1]\n    return c\nprint(prefix(\"abaabab\"), count(\"abaababaabaabab\", \"abaab\"))\n```", "options": ["[0, 0, 1, 1, 2, 3, 2] 2", "[0, 0, 1, 1, 2, 1, 2] 3", "[0, 0, 1, 0, 2, 3, 2] 3", "[0, 0, 1, 1, 2, 3, 2] 3"], "answer": 3, "explanation": "pi[i] is the length of the longest proper prefix of p[0..i] that is also its suffix. For abaabab: a b → 0 0, aba → 1, abaa → 1 (fall back from 'ab' to 'a'), abaab → 2, abaaba → 3, abaabab → after the mismatch fall back 3 → 1 → then 'ab' → 2. After a full match the matcher resumes from pi[m − 1] = 2 instead of 0, so overlapping matches are found: 'abaab' starts at 0, 5 and 8 → 3. Resetting k to 0 after a match finds only the non-overlapping ones.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-130", "question": "Z-array (z[i] = length of the longest common prefix of s and s[i:]). What is printed?\n```python\ndef z(s):\n    n = len(s); z = [0] * n; l = r = 0\n    for i in range(1, n):\n        if i < r: z[i] = min(r - i, z[i - l])\n        while i + z[i] < n and s[z[i]] == s[i + z[i]]: z[i] += 1\n        if i + z[i] > r: l, r = i, i + z[i]\n    return z\ns = \"aabcaabxaab\"\nzz = z(s)\nprint(zz, sum(1 for i in range(1, len(s)) if zz[i] >= 3))\n```", "options": ["[0, 1, 0, 0, 3, 1, 0, 0, 2, 1, 0] 2", "[0, 1, 0, 0, 4, 1, 0, 0, 3, 1, 0] 3", "[0, 1, 0, 0, 3, 1, 0, 0, 3, 1, 0] 2", "[0, 1, 0, 0, 3, 1, 0, 0, 3, 1, 0] 3"], "answer": 2, "explanation": "s = aabcaabxaab. Position 4 starts 'aabx…' which matches 'aabc' for 3 characters; position 8 starts 'aab' and the string ends, so 3. Inside the box [l, r) the algorithm copies z[i − l] capped at r − i, which is what keeps it O(n). Exactly two positions (4 and 8) have z ≥ 3, i.e. two occurrences of the 3-character prefix 'aab' after the start. z[0] is conventionally 0 (or n).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-131", "question": "Rabin–Karp over digits with base 10 and a deliberately tiny modulus 7. It returns (true matches, spurious hash hits). What is printed?\n```python\ndef rk(t, p, base=10, mod=7):\n    m = len(p); hp = ht = 0; hi = pow(base, m - 1, mod)\n    for i in range(m):\n        hp = (hp * base + int(p[i])) % mod\n        ht = (ht * base + int(t[i])) % mod\n    hits = spurious = 0\n    for i in range(len(t) - m + 1):\n        if ht == hp:\n            if t[i:i + m] == p: hits += 1\n            else: spurious += 1\n        if i + m < len(t):\n            ht = ((ht - int(t[i]) * hi) * base + int(t[i + m])) % mod\n    return hits, spurious\nprint(rk(\"3141592653589793\", \"26\"))\n```", "options": ["(1, 1)", "(1, 0)", "(2, 1)", "(1, 3)"], "answer": 0, "explanation": "The pattern 26 has hash 26 mod 7 = 5. Sliding over 3141592653589793, the 2-digit windows whose value ≡ 5 (mod 7) are 26 (true match) and 89 (89 = 7·12 + 5, a collision), so one hit and one spurious hit that costs a full character comparison. With a tiny modulus collisions are frequent, and an adversary can make every window collide, giving O(nm); a large random prime modulus makes them rare.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-132", "question": "Open addressing with linear probing (size 7, h(k) = k mod 7). Deletion leaves a tombstone 'X'; insert reuses the first tombstone; find stops only at an EMPTY slot and returns (found, probes). What is printed?\n```python\nM = 7\ntable = [None] * M\nDEL = \"X\"\ndef ins(k):\n    i = k % M\n    while table[i] not in (None, DEL): i = (i + 1) % M\n    table[i] = k\ndef find(k):\n    i, probes = k % M, 0\n    while True:\n        probes += 1\n        if table[i] is None: return False, probes\n        if table[i] == k: return True, probes\n        i = (i + 1) % M\nfor k in [10, 17, 24, 5, 3]: ins(k)\ntable[table.index(17)] = DEL\nins(31)\nprint(table, find(24), find(38))\n```", "options": ["[3, None, None, 10, 'X', 24, 5] (True, 3) (False, 2)", "[3, None, None, 10, 31, 24, 5] (False, 2) (False, 6)", "[3, 31, None, 10, 'X', 24, 5] (True, 3) (False, 3)", "[3, None, None, 10, 31, 24, 5] (True, 3) (False, 6)"], "answer": 3, "explanation": "10→3, 17→4, 24→5 (3, 4 taken), 5→6, 3→ 3,4,5,6 taken → 0. Deleting 17 must leave a tombstone: emptying slot 4 would break the probe chain for 24. 31 hashes to 3 and reuses the tombstone at 4. find(24) probes 3, 4, 5 → found in 3. find(38) (38 mod 7 = 3) walks 3, 4, 5, 6, 0 and stops at the empty slot 1: 6 probes. Tombstones keep searches correct but lengthen unsuccessful ones until the table is rebuilt.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-133", "question": "Largest rectangle under a histogram using a stack of (start index, height). What is printed?\n```python\ndef rect(h):\n    st, best = [], 0\n    for i, x in enumerate(h + [0]):\n        start = i\n        while st and st[-1][1] >= x:\n            j, y = st.pop()\n            best = max(best, y * (i - j)); start = j\n        st.append((start, x))\n    return best\nprint(rect([2, 4, 4, 1, 5, 6, 2, 3]), rect([3, 3, 3, 3]), rect([1, 2, 3, 4, 5]))\n```", "options": ["12 12 15", "10 12 9", "10 16 9", "8 12 9"], "answer": 1, "explanation": "When a bar is popped, the current index is the first bar to its right that is lower, and the stored start already extends left over all taller bars it replaced, so its rectangle is height × (i − start). The sentinel 0 flushes the stack. [2,4,4,1,5,6,2,3]: best is 5 × 2 = 10 (bars 5, 6); 4 × 2 = 8, 1 × 8 = 8, 2 × 4 = 8. [3,3,3,3]: 12. [1,2,3,4,5]: 3 × 3 = 9. The answer 15 adds the bars instead of taking the minimum height. O(n) total.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-134", "question": "Rain water trapped between bars, computed with two pointers. What is printed?\n```python\ndef water(h):\n    l, r, lm, rm, w = 0, len(h) - 1, 0, 0, 0\n    while l < r:\n        if h[l] < h[r]:\n            lm = max(lm, h[l]); w += lm - h[l]; l += 1\n        else:\n            rm = max(rm, h[r]); w += rm - h[r]; r -= 1\n    return w\nprint(water([4, 0, 3, 1, 5, 0, 2, 0, 4]), water([5, 4, 3, 2, 1]), water([2, 0, 2, 0, 2]))\n```", "options": ["18 10 2", "18 0 4", "14 0 4", "17 0 4"], "answer": 1, "explanation": "Move the side with the lower bar: the water above it is limited by its own side's running maximum, because the other side is already known to have a bar at least that tall. [4,0,3,1,5,0,2,0,4]: left part 4+1+3 = 8, right part 4+2+4 = 10, total 18. A strictly decreasing profile traps nothing. [2,0,2,0,2] traps 2 + 2. 10 is the decreasing case computed as if the right edge were a wall of height 5.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-135", "question": "Next greater element in a CIRCULAR array (scan the array twice, pushing indices only in the first pass). What is printed?\n```python\ndef nge_circ(a):\n    n = len(a); res = [-1] * n; st = []\n    for i in range(2 * n):\n        x = a[i % n]\n        while st and a[st[-1]] < x: res[st.pop()] = x\n        if i < n: st.append(i)\n    return res\nprint(nge_circ([3, 8, 4, 1, 2, 8, 0]))\n```", "options": ["[8, -1, 8, 2, 8, -1, -1]", "[8, -1, 8, 2, 8, 8, 3]", "[8, 8, 8, 2, 8, -1, 3]", "[8, -1, 8, 2, 8, -1, 3]"], "answer": 3, "explanation": "The second lap lets elements near the end find a larger value at the front. 0 at the end wraps around to 3. Both 8s are the maximum, and 'greater' is strict, so neither finds anything (−1); treating equal as greater gives the option with an 8 for index 5. Each index is pushed once and popped at most once, so 2n iterations total – O(n).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-136", "question": "Towers stand in a row. Two towers can see each other if every tower strictly between them is shorter than both. The function counts such pairs with a monotonic stack. What is printed?\n```python\ndef see(h):\n    st, pairs = [], 0\n    for x in h:\n        while st and st[-1] < x:\n            st.pop(); pairs += 1\n        if st: pairs += 1\n        while st and st[-1] == x: st.pop()\n        st.append(x)\n    return pairs\nprint(see([4, 2, 3, 1, 5]), see([3, 1, 2, 2, 5]))\n```", "options": ["7 6", "7 7", "10 6", "6 6"], "answer": 0, "explanation": "Scanning left to right, x sees every shorter tower it pops (they are not blocked) plus the first tower left that is ≥ x, which then blocks everything further. Equal towers: x sees the equal one but nothing behind it, so equals are popped after counting. [4,2,3,1,5]: (4,2) (2,3) (4,3) (3,1) (1,5) (3,5) (4,5) = 7. [3,1,2,2,5]: (3,1) (1,2) (3,2) (2,2) (2,5) (3,5) = 6 – the first 2 cannot see 5 past the second 2. 10 counts all pairs.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-137", "question": "A ticket number may lose exactly k digits; the remaining digits must keep their order and form the smallest possible number (leading zeros dropped). What is printed?\n```python\ndef smallest(num, k):\n    st = []\n    for d in num:\n        while k and st and st[-1] > d:\n            st.pop(); k -= 1\n        st.append(d)\n    st = st[:len(st) - k]\n    return \"\".join(st).lstrip(\"0\") or \"0\"\nprint(smallest(\"4205173\", 3), smallest(\"10200\", 1), smallest(\"123456\", 2))\n```", "options": ["205 0200 3456", "173 200 3456", "173 200 1234", "0173 200 1234"], "answer": 2, "explanation": "Greedy with a non-decreasing stack: whenever an earlier digit is larger than the next one, removing it lowers the most significant possible position. 4205173, k = 3: drop 4 (2 < 4), drop 2 (0 < 2), keep 0, 5, then drop 5 for 1 → 0173 → 173. 10200, k = 1: drop 1 → 0200 → 200. In an increasing string nothing is popped, so the leftover deletions come off the END → 1234 (dropping from the front gives 3456). O(n).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-138", "question": "Count subarrays whose sum is divisible by 3 using prefix sums and a remainder map. The second version imitates C's % operator (sign follows the dividend). What is printed?\n```python\ndef div_count(a, k):\n    seen = {0: 1}; s = c = 0\n    for x in a:\n        s = (s + x) % k\n        c += seen.get(s, 0)\n        seen[s] = seen.get(s, 0) + 1\n    return c\ndef c_style(a, k):\n    seen = {0: 1}; s = c = 0\n    for x in a:\n        s = s + x\n        r = abs(s) % k * (1 if s >= 0 else -1)\n        c += seen.get(r, 0)\n        seen[r] = seen.get(r, 0) + 1\n    return c\na = [4, -6, 2, -3, 5, 1]\nprint(div_count(a, 3), c_style(a, 3))\n```", "options": ["6 7", "7 7", "5 6", "7 6"], "answer": 3, "explanation": "Two prefixes with equal remainder bracket a subarray whose sum is a multiple of k. Prefix sums: 4, −2, 0, −3, 2, 3. Python's % maps them to 1, 1, 0, 0, 2, 0; with the initial 0 the classes are {0: 4, 1: 2, 2: 1} → C(4,2) + C(2,2) = 7. With C-style %, −2 gives −2 instead of 1, so the 4 and −2 prefixes land in different buckets and that pair is missed → 6. In C/C++/Java one must normalise ((s % k) + k) % k.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-139", "question": "Longest subarray with sum exactly 5 when the array contains NEGATIVE numbers: a shrink-when-too-big sliding window versus a prefix-sum map that stores the first index of each prefix. What is printed?\n```python\ndef window(a, k):\n    lo = s = best = 0\n    for hi, x in enumerate(a):\n        s += x\n        while s > k and lo <= hi: s -= a[lo]; lo += 1\n        if s == k: best = max(best, hi - lo + 1)\n    return best\ndef prefix_map(a, k):\n    first = {0: -1}; s = best = 0\n    for i, x in enumerate(a):\n        s += x\n        if s - k in first: best = max(best, i - first[s - k])\n        first.setdefault(s, i)\n    return best\na = [3, 4, -7, 1, 3, 3, -2, 1]\nprint(window(a, 5), prefix_map(a, 5))\n```", "options": ["5 7", "0 4", "0 7", "4 7"], "answer": 2, "explanation": "The sliding window assumes that extending the window never decreases the sum, which is false with negatives: here it shrinks past useful starts and never sees a sum of exactly 5 → 0. The prefix map looks for an earlier prefix equal to current − 5; storing only the FIRST occurrence maximises the length. Prefixes 0,3,7,0,1,4,7,5,6: at index 6 (prefix 5) the earliest prefix 0 is at −1 → length 7 (3+4−7+1+3+3−2 = 5). O(n).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-140", "question": "Total element copies when a dynamic array is filled with 100 items under three growth rules (cost, final capacity). What is printed?\n```python\ndef copies(n, grow):\n    cap, size, cost = 1, 0, 0\n    for _ in range(n):\n        if size == cap:\n            cost += size\n            cap = grow(cap)\n        size += 1\n    return cost, cap\nprint(copies(100, lambda c: 2 * c), copies(100, lambda c: c + c // 2 + 1), copies(100, lambda c: c + 10))\n```", "options": ["(127, 128) (196, 139) (460, 101)", "(127, 128) (261, 139) (460, 101)", "(99, 128) (261, 139) (4950, 101)", "(127, 128) (261, 139) (500, 110)"], "answer": 1, "explanation": "A copy of all current items happens whenever size reaches capacity. Doubling: 1+2+4+…+64 = 127, about n – O(1) amortised. Growth by ×1.5 (+1) still copies a geometric series, 261 here, a larger constant but still O(1) amortised. Growing by a constant 10 copies 1, 11, 21, …, 91 = 460 for only 100 items, and in general Θ(n²/10) – O(n) amortised per insert. A constant increment is the trap even though it wastes the least memory.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-141", "question": "A 'last position ≤ x' binary search with the loop capped at 50 iterations, returning (lo, iterations). What is printed?\n```python\ndef search(a, x):\n    lo, hi, steps = 0, len(a) - 1, 0\n    while lo < hi and steps < 50:\n        steps += 1\n        mid = (lo + hi) // 2\n        if a[mid] <= x: lo = mid\n        else: hi = mid - 1\n    return lo, steps\na = [1, 3, 5, 7, 9, 11]\nprint(search(a, 3), search(a, 7), search(a, 11))\n```", "options": ["(0, 50) (3, 3) (4, 50)", "(1, 2) (3, 3) (5, 3)", "(0, 50) (3, 3) (5, 3)", "(1, 50) (3, 3) (4, 50)"], "answer": 0, "explanation": "With mid = (lo + hi) // 2 and the update lo = mid, once hi = lo + 1 the midpoint equals lo; if a[mid] ≤ x, lo does not move and the loop never ends. x = 3: lo 0, hi 5 → hi 1 → mid 0 → lo stays 0 forever. x = 7 happens to finish at index 3. x = 11 reaches lo 4, hi 5 and sticks. The fix is the upper midpoint mid = (lo + hi + 1) // 2 whenever the branch is lo = mid.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-142", "question": "Packages must ship in order, one contiguous group per day; binary search on the daily capacity finds the smallest capacity that finishes within D days. What is printed?\n```python\ndef days_needed(w, cap):\n    d, cur = 1, 0\n    for x in w:\n        if cur + x > cap: d += 1; cur = 0\n        cur += x\n    return d\ndef min_cap(w, D):\n    lo, hi = max(w), sum(w)\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if days_needed(w, mid) <= D: hi = mid\n        else: lo = mid + 1\n    return lo\nw = [7, 2, 5, 10, 8, 1, 6]\nprint(min_cap(w, 3), min_cap(w, 2), min_cap(w, 7))\n```", "options": ["15 24 10", "14 23 10", "15 24 39", "13 20 10"], "answer": 0, "explanation": "days_needed is monotone non-increasing in the capacity, so we can binary search between max(w) (otherwise one package never fits) and sum(w). D = 3: capacity 15 gives [7,2,5] [10] [8,1,6]; 14 needs 4 days. D = 2: 24 gives [7,2,5,10] [8,1,6]. D = 7 (one per package) needs only max(w) = 10. Total O(n log(sum)). 39 ignores that D = 2 still permits a split.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-143", "question": "Minimum window of s containing every character of t WITH multiplicity, using a need-counter. What is printed?\n```python\nfrom collections import Counter\ndef min_window(s, t):\n    need, have, missing = Counter(t), {}, len(t)\n    lo, best = 0, (10**9, 0, 0)\n    for hi, ch in enumerate(s):\n        if need[ch] > 0: missing -= 1\n        need[ch] -= 1\n        if missing == 0:\n            while need[s[lo]] < 0: need[s[lo]] += 1; lo += 1\n            best = min(best, (hi - lo + 1, lo, hi))\n            need[s[lo]] += 1; missing += 1; lo += 1\n    return s[best[1]:best[2] + 1] if best[0] < 10**9 else \"\"\nprint(min_window(\"cabwefgewcwaefgcf\", \"cae\"), min_window(\"aabbaac\", \"aab\"), repr(min_window(\"ab\", \"aa\")))\n```", "options": ["cwae aab 'ab'", "cwae aab ''", "aefgc aab ''", "cwae aabb ''"], "answer": 1, "explanation": "need[c] > 0 means c is still missing; once missing hits 0 the left edge is advanced past surplus characters (need < 0), the window is recorded, and then one required character is released to look for a later window. 'cwae' (indices 9–12) is the shortest window with c, a, e. For aab the first three letters already work. t = 'aa' needs two a's but 'ab' has one, so the answer is empty. O(|s| + |t|).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-144", "question": "Shortest subarray with sum ≥ 5 in an array WITH negative numbers: an increasing deque of prefix-sum indices versus the usual shrinking window. What is printed?\n```python\nfrom collections import deque\ndef shortest(a, K):\n    P = [0]\n    for x in a: P.append(P[-1] + x)\n    dq, best = deque(), 10**9\n    for j in range(len(P)):\n        while dq and P[j] - P[dq[0]] >= K: best = min(best, j - dq.popleft())\n        while dq and P[dq[-1]] >= P[j]: dq.pop()\n        dq.append(j)\n    return best if best < 10**9 else -1\ndef naive_window(a, K):\n    lo = s = 0; best = 10**9\n    for hi, x in enumerate(a):\n        s += x\n        while s >= K: best = min(best, hi - lo + 1); s -= a[lo]; lo += 1\n    return best if best < 10**9 else -1\na = [2, -1, 2, -4, 3, 1, -2, 4]\nprint(shortest(a, 5), naive_window(a, 5))\n```", "options": ["4 4", "2 8", "4 8", "-1 8"], "answer": 2, "explanation": "With negatives, prefix sums are not monotone, so the shrinking window is wrong: it only shrinks while the sum is ≥ K and here reaches K only with the whole array → 8. The deque keeps prefix indices with increasing values: a later smaller prefix is always a better start, so larger ones are dropped from the back, and a front index is popped as soon as it yields a valid subarray (later ends could only be longer). Result: [3, 1, −2, 4] of length 4. O(n).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-145", "question": "Probe-sequence coverage for open addressing: how many distinct slots can the offsets i² (quadratic) and i(i+1)/2 (triangular) reach in tables of size m? What is printed?\n```python\ndef reach(m):\n    return len({(i * i) % m for i in range(m)})\ndef reach_tri(m):\n    return len({(i * (i + 1) // 2) % m for i in range(m)})\nprint(reach(16), reach(17), reach_tri(16), reach_tri(12))\n```", "options": ["16 9 16 12", "4 9 8 12", "4 17 16 8", "4 9 16 8"], "answer": 3, "explanation": "i² mod 16 only takes the values 0, 1, 4, 9 → 4 slots, so an insert can fail although 12 slots are free. For a prime m = 17 it reaches (m + 1)/2 = 9 slots, which is why quadratic probing needs a prime size and load ≤ ½. Triangular offsets are a permutation of all slots exactly when m is a power of two (16 → 16), but not for m = 12 (8). That is the reason power-of-two tables use i(i+1)/2.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-146", "question": "An LRU cache of capacity 3 (OrderedDict, oldest first) processes page requests. How many misses, and what is the final order?\n```python\nfrom collections import OrderedDict\ncap, c, miss = 3, OrderedDict(), 0\nfor op in \"A B C A D B E A C\".split():\n    if op in c: c.move_to_end(op)\n    else:\n        miss += 1\n        if len(c) == cap: c.popitem(last=False)\n        c[op] = 1\nprint(miss, \"\".join(c))\n```", "options": ["7 EAC", "8 ACE", "8 EAC", "6 BEA"], "answer": 2, "explanation": "A hit moves the page to the most-recent end; a miss on a full cache evicts the least recent (front). A B C: 3 misses. A: hit → B C A. D: evict B → C A D. B: evict C → A D B. E: evict A → D B E. A: evict D → B E A. C: evict B → E A C. 8 misses in 9 requests – the re-request of A just before D is what makes B, not A, the next victim. Both get and put are O(1) with a hash map + doubly linked list.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-147", "question": "Minimum number of brackets to INSERT to make a string balanced, returned as (total, unmatched ')', unmatched '('). What is printed?\n```python\ndef fix(s):\n    open_, add = 0, 0\n    for ch in s:\n        if ch == \"(\": open_ += 1\n        elif open_: open_ -= 1\n        else: add += 1\n    return add + open_, add, open_\nprint(fix(\"())(()(((\"), fix(\")))(((\"), fix(\"(()))(\"))\n```", "options": ["(5, 1, 4) (6, 3, 3) (2, 1, 1)", "(4, 1, 3) (6, 3, 3) (2, 1, 1)", "(5, 1, 4) (3, 3, 0) (1, 1, 0)", "(3, 1, 2) (6, 3, 3) (2, 1, 1)"], "answer": 0, "explanation": "Scan once: a ')' with no open '(' needs an inserted '('; every '(' still open at the end needs a ')'. '())(()(((': one stray ')' and 4 open → 5. ')))(((': 3 + 3 = 6 (the order matters – the same characters as '((()))' would need 0). '(()))(': one stray ')' and one open → 2. A single counter that may go negative and is reported as |count| gives 0 for ')))(((' – the classic wrong shortcut.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-148", "question": "Boyer–Moore majority vote WITHOUT the verification pass, returning (candidate, final counter). What is printed?\n```python\ndef vote(a):\n    cand, cnt = None, 0\n    for x in a:\n        if cnt == 0: cand = x\n        cnt += 1 if x == cand else -1\n    return cand, cnt\nprint(vote([2, 2, 1, 3, 1, 1, 4, 1, 1]), vote([1, 2, 3, 1, 2, 3, 3]), vote([5, 5, 6, 6, 7]))\n```", "options": ["(1, 3) (3, 0) (7, 1)", "(1, 1) (3, 1) (5, 1)", "(2, 3) (3, 1) (7, 1)", "(1, 3) (3, 1) (7, 1)"], "answer": 3, "explanation": "The vote cancels pairs of different values, so a TRUE majority (> n/2) always survives as the candidate – [2,2,1,3,1,1,4,1,1] gives 1 with net 3. But when no majority exists the survivor is arbitrary: [1,2,3,1,2,3,3] yields 3 although it occurs 3/7 times, and [5,5,6,6,7] yields 7, which occurs once. So a second O(n) counting pass is mandatory before reporting a majority. O(1) space.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-149", "question": "Inversions counted during merge sort (pairs i < j with a[i] > a[j]). What is printed?\n```python\ndef inv(a):\n    if len(a) <= 1: return a, 0\n    m = len(a) // 2\n    L, x = inv(a[:m]); R, y = inv(a[m:])\n    out, i, j, c = [], 0, 0, x + y\n    while i < len(L) and j < len(R):\n        if L[i] <= R[j]: out.append(L[i]); i += 1\n        else: out.append(R[j]); j += 1; c += len(L) - i\n    return out + L[i:] + R[j:], c\nprint(inv([5, 3, 8, 3, 1, 9, 2])[1], inv([4, 4, 4])[1], inv(list(range(10, 0, -1)))[1])\n```", "options": ["12 3 45", "12 0 45", "11 0 45", "12 0 55"], "answer": 1, "explanation": "When R[j] is taken before L[i], it is smaller than every remaining element of L, so it adds len(L) − i inversions at once – O(n log n) instead of O(n²). [5,3,8,3,1,9,2]: brute force confirms 12. Equal values are not inversions, and the merge takes from L on ties (≤), so [4,4,4] gives 0; using < there would count equal pairs and give 3. A reversed array of 10 has C(10, 2) = 45.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-150", "question": "One Hoare partition with the FIRST element (6) as pivot. What is printed (array after the partition, returned index)?\n```python\ndef hoare(a):\n    p = a[0]; i, j = -1, len(a)\n    while True:\n        i += 1\n        while a[i] < p: i += 1\n        j -= 1\n        while a[j] > p: j -= 1\n        if i >= j: return a, j\n        a[i], a[j] = a[j], a[i]\nprint(hoare([6, 3, 9, 6, 1, 8, 2, 7]))\n```", "options": ["([2, 3, 1, 6, 6, 8, 9, 7], 4)", "([2, 3, 1, 6, 9, 8, 6, 7], 3)", "([1, 2, 3, 6, 6, 7, 8, 9], 3)", "([2, 3, 1, 6, 9, 8, 6, 7], 4)"], "answer": 1, "explanation": "i stops at elements ≥ pivot and j at elements ≤ pivot, then they swap. Round 1: i = 0 (6), j = 6 (2) → swap. Round 2: i = 2 (9), j = 4 (1) → swap. Round 3: i = 3 (6), j = 3 (6) → i ≥ j, return 3. Unlike Lomuto, Hoare does NOT put the pivot in its final place: the result only guarantees a[0..3] ≤ 6 ≤ a[4..7], and an equal 6 is left on each side. Recurse on [lo, j] and [j + 1, hi].", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-151", "question": "Counting palindromic substrings (by position) with centre expansion over 2n − 1 centres. What is printed?\n```python\ndef pal(s):\n    c = 0\n    for center in range(2 * len(s) - 1):\n        l = center // 2; r = l + center % 2\n        while l >= 0 and r < len(s) and s[l] == s[r]: c += 1; l -= 1; r += 1\n    return c\nprint(pal(\"aabaa\"), pal(\"abcba\"), pal(\"aaaa\"))\n```", "options": ["9 5 10", "7 7 10", "9 7 6", "9 7 10"], "answer": 3, "explanation": "Each centre (a character or a gap) expands while the ends match, adding one palindrome per step. aabaa: 5 singles + 'aa' twice + 'aba' + 'aabaa' = 9. abcba: 5 + 'bcb' + 'abcba' = 7. aaaa: every substring is a palindrome, 4·5/2 = 10. Forgetting the even (gap) centres misses 'aa' and gives 7 for aabaa. O(n²) worst case; Manacher is O(n).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-152", "question": "Sum over all subarrays of (max − min), computed as Σ max − Σ min with two monotonic-stack passes, checked against brute force. What is printed?\n```python\ndef spread(a):\n    n = len(a); total = 0\n    for sign in (1, -1):\n        b = [sign * x for x in a]; st = []; left = [0] * n\n        for i in range(n):\n            while st and b[st[-1]] < b[i]: st.pop()\n            left[i] = i - (st[-1] if st else -1); st.append(i)\n        st = []; right = [0] * n\n        for i in range(n - 1, -1, -1):\n            while st and b[st[-1]] <= b[i]: st.pop()\n            right[i] = (st[-1] if st else n) - i; st.append(i)\n        total += sum(b[i] * left[i] * right[i] for i in range(n))\n    return total\na = [4, 1, 3, 2]\nprint(spread(a), sum(max(a[i:j]) - min(a[i:j]) for i in range(4) for j in range(i + 1, 5)))\n```", "options": ["14 14", "14 12", "12 12", "17 14"], "answer": 0, "explanation": "Negating the array turns 'contribution as minimum' into 'contribution as maximum', so one routine computes both: Σ max = 4+4+4+4+1+3+3+3+3+2 = 31, Σ min = 4+1+1+1+1+1+1+3+2+2 = 17, difference 14 – the same as the brute force. The ≤ vs < tie-breaking on the two sides is what keeps equal values from being counted twice. O(n) instead of O(n²).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-153", "question": "Merging files costs the size of the result each time. Compare the greedy 'always merge the two smallest' (heap) with merging left to right in sorted and in given order. What is printed?\n```python\nimport heapq\ndef merge_cost(a):\n    h = list(a); heapq.heapify(h); cost = 0\n    while len(h) > 1:\n        x = heapq.heappop(h) + heapq.heappop(h); cost += x; heapq.heappush(h, x)\n    return cost\ndef left_to_right(a):\n    s, cost = a[0], 0\n    for x in a[1:]: s += x; cost += s\n    return cost\na = [7, 5, 8, 6, 5]\nprint(merge_cost(a), left_to_right(sorted(a)), left_to_right(a))\n```", "options": ["72 72 89", "80 80 89", "72 80 89", "72 80 72"], "answer": 2, "explanation": "Each size is paid once per merge it takes part in, i.e. weighted by its depth in the merge tree – the Huffman argument shows merging the two smallest is optimal. Heap: 5+5 = 10, 6+7 = 13, 8+10 = 18, 13+18 = 31 → 72. Left to right on the sorted list keeps re-adding a growing prefix: 10, 16, 23, 31 → 80; sorting first does not make a chain optimal. In the given order: 12, 20, 26, 31 → 89. O(n log n).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-154", "question": "You must count pairs i < j with a[i] + a[j] ≤ T for n ≤ 2·10⁵ values up to 10⁹ in absolute value (time limit 1 s). Which plan passes?", "options": ["Nested loops over all pairs – about 2·10¹⁰ simple additions finish within 1 s in C++", "A hash map of complements as in two-sum, since a hash lookup answers '≤ T' in O(1)", "Prefix sums of the sorted array, since the number of valid pairs equals the prefix sum at index T", "Sort, then two pointers: for each left index move the right pointer down while the sum exceeds T and add (right − left) – O(n log n)"], "answer": 3, "explanation": "After sorting, if a[l] + a[r] ≤ T then every partner l + 1..r works for l, so each step either fixes l's count or discards r – both pointers move at most n times. n²/2 = 2·10¹⁰ pairs is ~100× too many for 1 s. A hash map answers equality queries only, not ranges. Prefix sums of VALUES say nothing about pair counts, and T is a value, not an index. Note that the answer can reach ~2·10¹⁰, so it needs a 64-bit counter.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-155", "question": "A service stores n = 10⁵ integer keys in a chained hash table with m = 1000 buckets and h(k) = k mod m. An attacker sends keys that are all multiples of 1000. What happens, and which fix actually removes the problem?", "options": ["Nothing serious: chaining keeps every insert O(1), so the total stays O(n)", "Growing the table to m = 2000 buckets spreads the keys over 2 buckets, which fixes the problem", "All keys land in bucket 0, so the n inserts cost Θ(n²) ≈ 5·10⁹ comparisons; randomising the hash (a seeded universal hash) restores O(1) expected per operation", "Using a prime number of buckets such as 997 is enough because then no fixed key pattern can collide"], "answer": 2, "explanation": "Insertion into a chain usually checks for an existing key, so the i-th insert scans i − 1 entries: Σ i ≈ n²/2. Doubling m to 2000 still puts multiples of 1000 into only 2 buckets. A prime modulus defeats this particular pattern, but an attacker who knows h can simply send multiples of 997. Only a hash chosen at random at runtime (universal hashing / SipHash-style seeds) makes the expected chain length n/m for every input. Java 8 additionally turns long chains into balanced trees (O(log n)).", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-156", "question": "An empty queue performs: enqueue 7, enqueue 2, enqueue 9, dequeue, enqueue 4, dequeue. Which element is now at the front?", "options": ["9", "4", "2", "7"], "answer": 0, "explanation": "FIFO: the two dequeues remove 7 and then 2 (the two oldest items). The queue is now 9, 4 with 9 at the front. '4' is the stack (LIFO) answer: the most recently added item.", "difficulty": "easy", "source": "TCS NQT · Wipro pattern"},
  {"id": "cs-dsa-linear-157", "question": "In a doubly linked list you are given a pointer to a node X somewhere in the middle. What is the time to delete X?", "options": ["O(n)", "O(1)", "O(log n)", "O(n²)"], "answer": 1, "explanation": "X knows both neighbours through its prev and next pointers, so deletion is X.prev.next = X.next and X.next.prev = X.prev – constant work. In a singly linked list you would need the predecessor, which costs O(n) to find from the head.", "difficulty": "easy", "source": "Accenture · Cognizant pattern"},
  {"id": "cs-dsa-linear-158", "question": "A hash table has 7 slots and uses h(k) = k mod 7. In which slot is the key 50 placed if that slot is empty?", "options": ["7", "0", "1", "6"], "answer": 2, "explanation": "50 = 7 × 7 + 1, so 50 mod 7 = 1. Slot indices run 0–6, so '7' is not even a valid slot; the quotient is 7, not the remainder.", "difficulty": "easy", "source": "Infosys · Capgemini pattern"},
  {"id": "cs-dsa-linear-159", "question": "Operators have the usual precedence (* and / above + and −, all left-associative). What is the postfix form of A * (B + C) / D − E?", "options": ["A B C + D / * E −", "A B C + * D E − /", "A B + C * D / E −", "A B C + * D / E −"], "answer": 3, "explanation": "The bracket is evaluated first (B C +), then * with A, then / with D (left to right, same precedence), and finally − E: A B C + * D / E −. 'A B C + D / *' does the division before the multiplication, which breaks left-associativity.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-160", "question": "What is the value of the prefix expression + * 3 4 − 9 / 8 2 ?", "options": ["17", "12", "8", "21"], "answer": 0, "explanation": "Scan right to left with a stack (the first popped value is the LEFT operand): 8 / 2 = 4; 9 − 4 = 5; 3 * 4 = 12; 12 + 5 = 17. Taking the first popped value as the RIGHT operand instead turns 9 − 4 into 4 − 9 and 8 / 2 into 2 / 8, which derails the result.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "cs-dsa-linear-161", "question": "Selection sort (find the minimum of the unsorted part, swap it to the front only if it is not already there) sorts [29, 10, 14, 37, 13] into ascending order. How many swaps does it make?", "options": ["4", "3", "5", "2"], "answer": 1, "explanation": "Pass 1: min 10 swaps with 29 → [10, 29, 14, 37, 13]. Pass 2: min 13 swaps with 29 → [10, 13, 14, 37, 29]. Pass 3: 14 is already in place (no swap). Pass 4: 29 swaps with 37. Total 3. Counting a swap in every pass gives n − 1 = 4.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-162", "question": "Binary search with mid = (lo + hi) / 2 (integer division) looks for 31 in [3, 9, 14, 20, 27, 31, 40] (0-based). Which indices are probed, in order?", "options": ["3, 4, 5", "3, 5, 6", "3, 5", "4, 5"], "answer": 2, "explanation": "lo = 0, hi = 6 → mid 3 (20 < 31) → lo = 4. mid = (4 + 6)/2 = 5 → a[5] = 31, found. Two probes: 3, 5. Probing 4 next would be linear scanning, not halving.", "difficulty": "moderate", "source": "Infosys · Cognizant pattern"},
  {"id": "cs-dsa-linear-163", "question": "Starting from an empty stack: push 5, push 3, pop, push 8, push 2, pop, pop, push 7, push 1. What are the stack contents from top to bottom?", "options": ["1, 7, 8, 5", "5, 7, 1", "1, 7, 2, 5", "1, 7, 5"], "answer": 3, "explanation": "After push 5, 3 and pop: [5]. Push 8, 2 → [5, 8, 2]; two pops remove 2 then 8 → [5]. Push 7, 1 → [5, 7, 1]; top first: 1, 7, 5. '5, 7, 1' lists bottom to top.", "difficulty": "moderate", "source": "Wipro · Capgemini pattern"},
  {"id": "cs-dsa-linear-164", "question": "A circular queue uses an array of size 5 (indices 0–4); front is the index of the first element and rear is the index of the last element. If front = 3 and rear = 1 and the queue is not empty, how many elements does it hold?", "options": ["4", "3", "2", "5"], "answer": 0, "explanation": "The elements occupy 3, 4, 0, 1 (wrapping past the end): 4 elements. Formula: (rear − front + N) mod N + 1 = (1 − 3 + 5) mod 5 + 1 = 4. Using rear − front = −2 or forgetting the +1 gives the other values.", "difficulty": "moderate", "source": "TCS NQT · Accenture pattern"},
  {"id": "cs-dsa-linear-165", "question": "Double hashing in a table of size 11 uses h1(k) = k mod 11 and h2(k) = 7 − (k mod 7); probe i goes to (h1 + i·h2) mod 11. Keys 14, 25, 36 are inserted in that order. In which slot does 36 end up?", "options": ["4", "9", "5", "1"], "answer": 1, "explanation": "14 → 14 mod 11 = 3. 25 → 3 is taken; h2(25) = 7 − 4 = 3, so it goes to 6. 36 → 3 taken; h2(36) = 7 − 1 = 6: (3 + 6) mod 11 = 9, which is free. Linear probing would have put 36 at slot 4 and 25 at 4 as well; '5' uses the h2 of 25 for 36.", "difficulty": "moderate", "source": "Infosys · Wipro pattern"},
  {"id": "cs-dsa-linear-166", "question": "How many DISTINCT palindromic substrings (counted as strings, not by position) does 'abaab' have?", "options": ["7", "6", "5", "4"], "answer": 2, "explanation": "The palindromes are a, b, aba, aa and baab. Counting occurrences by position instead (a×3, b×2, aba, aa, baab) gives 8; forgetting the even-length ones (aa, baab) gives 3. Distinct strings: 5.", "difficulty": "moderate", "source": "TCS Digital · Infosys pattern"},
  {"id": "cs-dsa-linear-167", "question": "For each element of [4, 10, 5, 8, 20, 15, 3, 12], find the nearest SMALLER element to its LEFT (−1 if none) using a monotonic stack. What is the result?", "options": ["−1, 4, 4, 5, 8, 15, −1, 3", "−1, 4, 4, 5, 8, 8, −1, −1", "−1, −1, 4, 5, 8, 8, −1, 3", "−1, 4, 4, 5, 8, 8, −1, 3"], "answer": 3, "explanation": "Keep an increasing stack, popping every value ≥ the current one. 5 pops 10 → answer 4. 15 pops 20 → answer 8 (not 20, and not 15 itself). 3 empties the stack → −1. 12 sees 3 on top → 3. The option with 15 for 15's slot forgets to pop larger values; the one ending −1 forgets that 3 stays on the stack.", "difficulty": "hard", "source": "Product company OA · Infosys pattern"},
  {"id": "cs-dsa-linear-168", "question": "The numbers 1, 2, 3, 4, 5 are pushed onto a stack in that order, and pops may happen at any time. Which of these pop sequences is IMPOSSIBLE?", "options": ["4, 2, 3, 5, 1", "3, 2, 5, 4, 1", "2, 4, 3, 5, 1", "1, 3, 5, 4, 2"], "answer": 0, "explanation": "To pop 4 first, 1, 2, 3 must already be on the stack with 3 on top. The next pop can only be 3 (or a later push), never 2, which is buried under 3. The other three sequences can all be produced: e.g. 3 2 5 4 1 = push 1–3, pop 3, pop 2, push 4, 5, pop 5, 4, 1.", "difficulty": "hard", "source": "TCS Digital · Wipro pattern"},
  {"id": "cs-dsa-linear-169", "question": "Top-down merge sort (split until single elements, then merge) sorts an array of 13 elements. How many times is the merge step called?", "options": ["13", "12", "4", "26"], "answer": 1, "explanation": "Each merge combines two pieces into one. Starting with 13 single-element pieces and ending with 1, you need exactly 13 − 1 = 12 merges, regardless of how the splits fall. '4' is the recursion depth ⌈log₂ 13⌉, not the number of merges.", "difficulty": "hard", "source": "Infosys · Accenture pattern"},
  {"id": "cs-dsa-linear-170", "question": "Insertion sort (shift larger elements right; one key comparison per inner-loop test) sorts [2, 4, 1, 3, 5] into ascending order. How many key comparisons does it make in total?", "options": ["4", "5", "6", "10"], "answer": 2, "explanation": "i=1: 4 vs 2 (1). i=2: 1 vs 4, 1 vs 2, then j reaches −1 with no further comparison (2). i=3: 3 vs 4, 3 vs 2 stop (2). i=4: 5 vs 4 stop (1). Total 6. The number of SHIFTS (inversions) is 3; '10' is the worst case n(n−1)/2.", "difficulty": "hard", "source": "TCS Digital · Infosys pattern"},
  {"id": "cs-dsa-linear-171", "question": "Using a sliding window, what is the length of the longest contiguous subarray of [1, 2, 1, 3, 4, 3, 5, 3, 3] that contains at most 2 distinct values?", "options": ["3", "5", "6", "4"], "answer": 3, "explanation": "Candidates: [1, 2, 1] (3), [3, 4, 3] (3), [5, 3, 3] (3) and [3, 5, 3, 3] at indices 5–8 (4). Any longer window picks up a third value (e.g. 4 before 3, 5, 3, 3). '5' would need [4, 3, 5, 3, 3], which has three distinct values.", "difficulty": "hard", "source": "Product company OA · Infosys pattern"},
  {"id": "cs-dsa-linear-172", "question": "A chained hash table has 5 buckets, h(k) = k mod 5, and every new key is inserted at the HEAD of its chain. Keys 12, 7, 22, 3, 17, 2 are inserted in that order. What does bucket 2 hold, from head to tail?", "options": ["2 → 17 → 22 → 7 → 12", "12 → 7 → 22 → 17 → 2", "2 → 17 → 3 → 22 → 7 → 12", "2 → 22 → 12 → 17 → 7"], "answer": 0, "explanation": "12, 7, 22, 17 and 2 all leave remainder 2 (3 goes to bucket 3). Head insertion reverses arrival order: the last key inserted (2) is first. '12 → … → 2' is tail insertion; the option containing 3 miscomputes 3 mod 5.", "difficulty": "hard", "source": "Infosys · Wipro pattern"},
  {"id": "cs-dsa-linear-173", "question": "The list 1 → 2 → 3 → 4 → 5 → 6 → 7 → 8 is reversed in groups of k = 3 nodes; a final group with fewer than k nodes is left as it is. What is the result?", "options": ["3 → 2 → 1 → 6 → 5 → 4 → 8 → 7", "3 → 2 → 1 → 6 → 5 → 4 → 7 → 8", "8 → 7 → 6 → 5 → 4 → 3 → 2 → 1", "1 → 2 → 3 → 6 → 5 → 4 → 7 → 8"], "answer": 1, "explanation": "Groups: (1 2 3) → 3 2 1, (4 5 6) → 6 5 4, and the leftover (7 8) has only 2 nodes, so it stays 7 → 8. '… 8 → 7' is the variant that also reverses a short final group, which the question rules out.", "difficulty": "hard", "source": "Product company OA · Infosys pattern"},
  {"id": "cs-dsa-linear-174", "question": "A singly linked list holds 10 → 21 → 32 → 43 → 54 → 65. It is rearranged so that all nodes at ODD positions (1st, 3rd, …) come first, followed by the nodes at even positions, each group keeping its relative order. What is the result?", "options": ["21 → 43 → 65 → 10 → 32 → 54", "10 → 32 → 54 → 65 → 43 → 21", "10 → 32 → 54 → 21 → 43 → 65", "10 → 21 → 32 → 43 → 54 → 65"], "answer": 2, "explanation": "Positions, not values, decide: positions 1, 3, 5 hold 10, 32, 54 and positions 2, 4, 6 hold 21, 43, 65. Splitting by ODD VALUES (21, 43, 65 first) is the trap; the result is built by relinking two chains in one pass with O(1) extra space.", "difficulty": "hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-175", "question": "The juggling algorithm rotates an array of n = 12 elements left by k = 8 positions by following cycles of the form i → i + k (mod n). How many cycles does it process, and how many elements are in each?", "options": ["8 cycles of 1", "1 cycle of 12", "3 cycles of 4", "4 cycles of 3"], "answer": 3, "explanation": "The number of cycles is gcd(n, k) = gcd(12, 8) = 4, each of length n / gcd = 3: e.g. 0 → 8 → 4 → 0. '3 cycles of 4' swaps the two numbers; a single cycle happens only when gcd(n, k) = 1.", "difficulty": "hard", "source": "TCS Digital · Infosys pattern"},
  {"id": "cs-dsa-linear-176", "question": "Interpolation search (pos = lo + (key − a[lo]) · (hi − lo) / (a[hi] − a[lo]), integer division) looks for 32 in [1, 2, 4, 8, 16, 32, 64, 128] (0-based). How many probes does it make before finding 32?", "options": ["4", "1", "3", "6"], "answer": 0, "explanation": "The values grow exponentially, so the linear estimate keeps landing too far left. Probe 1: 0 + 31·7/127 = 1 (value 2) → lo = 2. Probe 2: 2 + 28·5/124 = 3 (value 8) → lo = 4. Probe 3: 4 + 16·3/112 = 4 (value 16) → lo = 5. Probe 4: index 5 = 32. Four probes – more than binary search needs here (3). One probe happens only for evenly spaced data, where interpolation search shines.", "difficulty": "hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-177", "question": "What is the sum of min(subarray) over all contiguous subarrays of [2, 5, 1, 4, 3]? (A monotonic stack counts, for each element, how many subarrays it is the minimum of.)", "options": ["15", "28", "25", "31"], "answer": 1, "explanation": "a[i] is the minimum of (choices of left end) × (choices of right end) subarrays, extending until a smaller element. 2: 1 × 2 → 2·2 = 4; 5: 1 × 1 → 5; 1: 3 × 3 → 9; 4: 1 × 1 (3 to its right is smaller) → 4; 3: 2 × 1 (it can extend left over 4) → 6. Total 4 + 5 + 9 + 4 + 6 = 28. Summing the elements once (15) ignores that each element is the minimum of several subarrays.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-178", "question": "What is the length of the longest substring of ')()())(()())' that is a valid (balanced) parentheses string?", "options": ["4", "10", "6", "12"], "answer": 2, "explanation": "Use a stack of indices with a sentinel for the last unmatched ')'. '()()' at indices 1–4 has length 4; the ')' at 5 is unmatched and resets the base; '(()())' at 6–11 is length 6. The two valid runs are separated by the unmatched ')', so they cannot be joined into 10. Counting matched pairs overall (5 pairs → 10) is the trap.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-179", "question": "The stock span of day i is the number of consecutive days ending at day i whose price is ≤ the price on day i. For prices [31, 27, 14, 21, 30, 18, 25, 40], what are the spans?", "options": ["1, 1, 1, 2, 3, 1, 2, 8", "1, 1, 1, 2, 4, 1, 2, 3", "1, 2, 3, 4, 5, 6, 7, 8", "1, 1, 1, 2, 4, 1, 2, 8"], "answer": 3, "explanation": "With a stack of indices holding decreasing prices: 21 pops 14 → span 2; 30 pops 21 and 27 → span 4 (days 27, 14, 21, 30); 25 pops 18 → span 2; 40 pops everything → span 8. '3' for day 5 forgets that 14 was already absorbed into 21's span; '3' for the last day stops at 30 instead of continuing past 31.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-180", "question": "What is the minimum number of swaps (of any two elements) needed to sort the permutation [4, 3, 1, 2, 6, 5] into ascending order?", "options": ["4", "3", "5", "6"], "answer": 0, "explanation": "Decompose into cycles of 'value v belongs at position v': positions 1 → 4 → 2 → 3 → 1 form a 4-cycle (needs 3 swaps) and 5 ↔ 6 is a 2-cycle (1 swap). Minimum = n − (number of cycles) = 6 − 2 = 4. Adjacent-swap counting (inversions) gives a larger number; '3' sees only the long cycle.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-181", "question": "A stack-based decoder expands k[s] into s repeated k times (nesting allowed). What does '2[x3[y]z]q' decode to?", "options": ["xyyyzqxyyyzq", "xyyyzxyyyzq", "xyzxyzxyzq", "xyyyzq"], "answer": 1, "explanation": "Innermost first: 3[y] = yyy, so the bracket is xyyyz; 2[…] doubles it to xyyyzxyyyz; q lies outside every bracket and is appended once. Applying 2 to the trailing q as well gives xyyyzqxyyyzq; repeating 'xyz' three times gives xyzxyzxyzq.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-182", "question": "Adjacent equal pairs are removed repeatedly with a stack until none remain. What is left of 'pqqprrsttsx'?", "options": ["ssx", "px", "x", "(empty)"], "answer": 2, "explanation": "Stack trace: p, q, q pops q → [p]; p pops p → []; r, r cancel; s; t, t cancel → [s]; s cancels s → []; x → [x]. Removing only the pairs visible in the ORIGINAL string (qq, rr, tt) and stopping leaves 'ppssx' → 'ssx' after one more round – the stack does all rounds in one pass.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-183", "question": "An array is split into the MAXIMUM number of contiguous chunks such that sorting each chunk separately and concatenating them gives the fully sorted array. How many chunks are possible for [3, 1, 2, 6, 4, 5, 7, 9, 8]?", "options": ["3", "5", "9", "4"], "answer": 3, "explanation": "For a permutation of 1..n, a chunk can end at position i exactly when max(prefix) = i. Prefix maxima: 3, 3, 3, 6, 6, 6, 7, 9, 9 → equal to i at i = 3, 6, 7, 9 → chunks [3 1 2] [6 4 5] [7] [9 8]. Forgetting that [7] stands alone gives 3.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-184", "question": "An extended Boyer–Moore vote keeps two candidates to find every value occurring MORE than n/3 times, then verifies them with a second pass. For [5, 1, 5, 2, 1, 5, 3, 1, 1], which values are reported?", "options": ["1 only", "5 and 1", "5 only", "none"], "answer": 0, "explanation": "n = 9, so a value must appear more than 3 times. 1 appears 4 times and 5 appears 3 times, so only 1 qualifies even though both survive as candidates. That is why the verification pass is required; skipping it reports 5 as well.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-185", "question": "Only the head pointer of a singly linked list of n nodes is known (no length is stored). What is the time to reach its middle node?", "options": ["O(1)", "O(n)", "O(log n)", "O(√n)"], "answer": 1, "explanation": "A linked list has no index arithmetic: you must walk node by node (or run slow/fast pointers), touching about n/2 nodes – O(n). O(1) access to the middle is an array property; binary search on a linked list is not O(log n) for the same reason.", "difficulty": "easy", "source": "Accenture · Cognizant pattern"},
  {"id": "cs-dsa-linear-186", "question": "An empty deque performs push_front(1), push_front(2), push_front(3) and then pop_back(). Which value is removed?", "options": ["3", "2", "1", "The deque is empty"], "answer": 2, "explanation": "After three push_front calls the deque reads 3, 2, 1 from front to back. pop_back removes from the back, which is the first value pushed: 1. '3' would be pop_front.", "difficulty": "easy", "source": "TCS NQT · Wipro pattern"},
  {"id": "cs-dsa-linear-187", "question": "A sorted array holds n elements and has spare capacity. What is the worst-case time to insert a new element so that the array stays sorted?", "options": ["O(log n)", "O(1)", "O(n log n)", "O(n)"], "answer": 3, "explanation": "Binary search finds the position in O(log n), but every element after that position must shift one place right, which is O(n) when inserting at the front. Re-sorting (O(n log n)) is never necessary.", "difficulty": "easy", "source": "Infosys · Capgemini pattern"},
  {"id": "cs-dsa-linear-188", "question": "Counting sort on [2, 0, 2, 1, 0, 2] (values 0–2) builds count[v] and then turns it into cumulative counts, count[v] = number of elements ≤ v. What is the cumulative count array?", "options": ["[2, 3, 6]", "[2, 1, 3]", "[0, 2, 3]", "[2, 3, 5]"], "answer": 0, "explanation": "Frequencies are 0: 2, 1: 1, 2: 3 → [2, 1, 3]. Running sums give [2, 3, 6]; the last entry always equals n = 6. Each cumulative value is one past the final position of that value, which is what makes the stable placement pass work. [0, 2, 3] is the exclusive (starting-index) version.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-189", "question": "Two pointers start at both ends of the sorted array [1, 3, 4, 6, 8, 11] to find pairs of DIFFERENT positions with sum 12 (move left if the sum is small, right if it is large, both on a match). How many pairs are found?", "options": ["3", "2", "1", "0"], "answer": 1, "explanation": "1 + 11 = 12 (match, move both) → 3 + 8 = 11 < 12 → 4 + 8 = 12 (match) → now l and r cross at 6. Pairs: (1, 11) and (4, 8). 6 + 6 would need the same position twice, which is excluded, so '3' is wrong.", "difficulty": "moderate", "source": "Infosys · Wipro pattern"},
  {"id": "cs-dsa-linear-190", "question": "A hash map starts with capacity 16 and doubles its capacity whenever the number of keys EXCEEDS 0.75 × capacity. What is its capacity after 25 distinct keys have been inserted?", "options": ["32", "128", "64", "48"], "answer": 2, "explanation": "The 13th key exceeds 12 = 0.75 × 16 → capacity 32 (threshold 24). The 25th key exceeds 24 → capacity 64. Stopping at 32 forgets the second resize; 25 keys in 32 slots would be a load factor of 0.78.", "difficulty": "moderate", "source": "Product company OA · Infosys pattern"},
  {"id": "cs-dsa-linear-191", "question": "Bubble sort (each pass compares adjacent pairs left to right and swaps if out of order) runs on [6, 2, 9, 1, 5]. What is the array after the first TWO passes?", "options": ["[2, 6, 1, 5, 9]", "[1, 2, 5, 6, 9]", "[2, 1, 6, 5, 9]", "[2, 1, 5, 6, 9]"], "answer": 3, "explanation": "Pass 1 carries 9 to the end: [2, 6, 1, 5, 9]. Pass 2 carries 6 to the second-last slot: 2 < 6 (no swap), 6 > 1 swap, 6 > 5 swap → [2, 1, 5, 6, 9]. [2, 6, 1, 5, 9] is the state after only one pass; the fully sorted array needs a third pass.", "difficulty": "moderate", "source": "TCS NQT · Accenture pattern"},
  {"id": "cs-dsa-linear-192", "question": "The array [1, 2, 3, 4, 5, 6] is first rotated RIGHT by 2 positions and then rotated LEFT by 5 positions. What is the result?", "options": ["[4, 5, 6, 1, 2, 3]", "[3, 4, 5, 6, 1, 2]", "[6, 1, 2, 3, 4, 5]", "[5, 6, 1, 2, 3, 4]"], "answer": 0, "explanation": "Rotations compose by adding offsets: right 2 then left 5 = left 3 (mod 6). Left 3 of [1..6] is [4, 5, 6, 1, 2, 3]. Step by step: right 2 → [5, 6, 1, 2, 3, 4]; left 5 → [4, 5, 6, 1, 2, 3].", "difficulty": "moderate", "source": "Wipro · Capgemini pattern"},
  {"id": "cs-dsa-linear-193", "question": "What is the longest common prefix of the strings interview, internet, interval and intern?", "options": ["intern", "inter", "int", "interv"], "answer": 1, "explanation": "Compare column by column: i, n, t, e, r are shared by all four. At index 5 the letters are v, n, v, n – they differ, so the prefix stops at 'inter'. 'intern' is common only to internet and intern.", "difficulty": "moderate", "source": "Infosys · Cognizant pattern"},
  {"id": "cs-dsa-linear-194", "question": "The first k = 4 elements of the queue 1, 2, 3, 4, 5, 6 (front first) are reversed using a stack: dequeue 4 items onto the stack, pop them back into the queue, then move the remaining n − k items from front to back. What is the queue now, front first?", "options": ["5, 6, 4, 3, 2, 1", "1, 2, 3, 4, 6, 5", "4, 3, 2, 1, 5, 6", "6, 5, 4, 3, 2, 1"], "answer": 2, "explanation": "After the stack step the queue is 5, 6, 4, 3, 2, 1 (the reversed block went to the back). Rotating the 2 untouched items 5, 6 from front to back gives 4, 3, 2, 1, 5, 6. Forgetting the final rotation leaves 5, 6, 4, 3, 2, 1.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-dsa-linear-195", "question": "k sorted lists contain N elements in total. They are merged into one sorted list by repeatedly taking the smallest head from a min-heap that holds one element per list. What is the time complexity?", "options": ["O(N log N)", "O(N k)", "O(k log N)", "O(N log k)"], "answer": 3, "explanation": "The heap never holds more than k entries, so each of the N extract-min + insert pairs costs O(log k): O(N log k) overall. Concatenating and sorting would be O(N log N); scanning all k heads for each output element is O(N k).", "difficulty": "hard", "source": "Product company OA · Infosys pattern"},
  {"id": "cs-dsa-linear-196", "question": "A deque of indices gives the MINIMUM of every window of size 3 in [4, 2, 12, 3, 8, 1, 7]. What are the window minima?", "options": ["2, 2, 3, 1, 1", "2, 2, 3, 3, 1", "4, 2, 3, 1, 1", "2, 3, 3, 1, 1"], "answer": 0, "explanation": "Windows: [4 2 12] → 2, [2 12 3] → 2, [12 3 8] → 3, [3 8 1] → 1, [8 1 7] → 1. The deque keeps increasing values; 3 evicts 12, and 1 evicts 8 and 3. '3, 3' for the fourth window ignores the newly arrived 1.", "difficulty": "hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-197", "question": "A hash table of size 10 uses linear probing. Slots 2, 3, 4, 7 and 8 are occupied and all others are empty (no deletions have happened). An UNSUCCESSFUL search is made for a key whose hash is 2. How many slots are examined?", "options": ["3", "4", "1", "6"], "answer": 1, "explanation": "The search walks 2, 3, 4 (all occupied, none match) and stops at the first empty slot, 5: 4 slots examined. The empty slot must be checked too – that is how the search knows the key is absent – so '3' undercounts.", "difficulty": "hard", "source": "Infosys · Accenture pattern"},
  {"id": "cs-dsa-linear-198", "question": "Quickselect with Lomuto partition (pivot = last element) looks for the 3rd smallest element of [7, 2, 9, 4, 3, 8], recursing only into the side that contains the target. How many partition calls are made?", "options": ["1", "2", "4", "3"], "answer": 2, "explanation": "Target index k = 2. Call 1 (whole array, pivot 8) puts 8 at index 4 → array [7, 2, 4, 3, 8, 9] → go left. Call 2 on indices 0–3 (pivot 3) puts 3 at index 1 → [2, 3, 4, 7, …] → go right. Call 3 on indices 2–3 (pivot 7) puts 7 at index 3 → go left. Call 4 on the one-element range 2–2 puts 4 at index 2 = k. Answer 4 with 4 partition calls; stopping the count when the range first contains the answer gives 3.", "difficulty": "hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-199", "question": "Binary search finds the index of the minimum of the rotated sorted array [15, 18, 22, 3, 6, 9, 12] using: mid = (lo + hi) / 2; if a[mid] > a[hi] then lo = mid + 1 else hi = mid; stop when lo == hi. What index is returned, and how many loop iterations run?", "options": ["index 3, 2 iterations", "index 4, 3 iterations", "index 0, 3 iterations", "index 3, 3 iterations"], "answer": 3, "explanation": "lo=0, hi=6: mid 3, a[3] = 3 ≤ 12 → hi = 3. lo=0, hi=3: mid 1, 18 > 3 → lo = 2. lo=2, hi=3: mid 2, 22 > 3 → lo = 3 = hi. Three iterations, returning index 3. Stopping as soon as a[mid] is the minimum (after the first probe) gives '2 iterations', but this loop only stops when lo == hi. Comparing with a[hi] (not a[lo]) is what makes the rule work for both rotated and unrotated arrays.", "difficulty": "hard", "source": "Product company OA · Infosys pattern"},
  {"id": "cs-dsa-linear-200", "question": "The sorted array [3, 4, 7, 10, 11] contains some positive integers. What is the 4th positive integer MISSING from it?", "options": ["6", "5", "8", "9"], "answer": 0, "explanation": "Missing positives in order: 1, 2, 5, 6, 8, 9, … → the 4th is 6. In O(log n): before a[i] there are a[i] − (i + 1) missing numbers (2, 2, 4, 6, 6), so the answer lies between 4 and 7: 4 + (4 − 2) = 6. '8' counts missing numbers after 7 only.", "difficulty": "hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-201", "question": "For [2, 3, 0, 4], out[i] is the product of all elements except a[i], computed with prefix and suffix products (no division). What is out?", "options": ["[0, 0, 0, 0]", "[0, 0, 24, 0]", "[12, 8, 24, 6]", "[0, 0, 24, 6]"], "answer": 1, "explanation": "Only the position of the single zero gets a non-zero product: 2·3·4 = 24. Every other position includes the 0 → 0. The division trick (total / a[i]) fails here because the total is 0 and 0/0 is undefined; [12, 8, 24, 6] is what you get by ignoring the zero.", "difficulty": "hard", "source": "Infosys · Accenture pattern"},
  {"id": "cs-dsa-linear-202", "question": "The intervals [1, 4], [6, 8], [2, 3], [8, 10], [12, 13] are sorted by start and merged (intervals that touch at an endpoint also merge). How many intervals remain?", "options": ["4", "2", "3", "5"], "answer": 2, "explanation": "Sorted: [1,4], [2,3], [6,8], [8,10], [12,13]. [2,3] is inside [1,4]; [8,10] touches [6,8] → [6,10]; [12,13] stands alone. Result [1,4], [6,10], [12,13]: 3. Treating touching intervals as separate gives 4.", "difficulty": "hard", "source": "Product company OA · Infosys pattern"},
  {"id": "cs-dsa-linear-203", "question": "A 'leader' is an element strictly greater than every element to its right (the last element is always a leader). Scanning from the right, which leaders does [12, 30, 7, 18, 9, 11, 4] have, in left-to-right order?", "options": ["30, 18, 11", "12, 30, 18, 11, 4", "30, 11, 4", "30, 18, 11, 4"], "answer": 3, "explanation": "From the right, keep the running maximum: 4 (leader), 11 > 4 (leader), 9 no, 18 > 11 (leader), 7 no, 30 > 18 (leader), 12 no. One O(n) pass. Leaving out 4 forgets that the last element always qualifies; 12 is not a leader because 30 lies to its right.", "difficulty": "hard", "source": "TCS Digital · Infosys pattern"},
  {"id": "cs-dsa-linear-204", "question": "The words stop, pots, opts, post, tops, spot, pot, top are grouped so that anagrams share a group (key = the sorted letters). How many groups are there, and how big is the largest?", "options": ["2 groups, largest 6", "1 group, largest 8", "3 groups, largest 4", "2 groups, largest 4"], "answer": 0, "explanation": "The six 4-letter words all sort to 'opst'; pot and top sort to 'opt'. Words of different lengths can never be anagrams, so the 3-letter ones form their own group: 2 groups, sizes 6 and 2. Grouping by the SET of letters would wrongly merge all eight into one group.", "difficulty": "hard", "source": "Infosys · Wipro pattern"},
  {"id": "cs-dsa-linear-205", "question": "A stack is built from two queues with a costly push: enqueue x into the empty queue Q2, move every element of Q1 into Q2 one by one, then swap the names Q1 and Q2. Counting each enqueue and each dequeue as one operation, how many operations does the 5th push cost (after four pushes and no pops)?", "options": ["5", "9", "8", "4"], "answer": 1, "explanation": "Q1 holds 4 elements. The push does 1 enqueue of x plus, for each of the 4 old elements, 1 dequeue and 1 enqueue: 1 + 2·4 = 9. This keeps the newest element at the front of Q1, so pop is a single dequeue. '5' counts only enqueues; '8' forgets the enqueue of x.", "difficulty": "hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-206", "question": "With at most k = 2 character replacements, what is the length of the longest substring of 'AABCABBB' that can be turned into a single repeated letter? (Sliding window: window length − count of its most frequent letter ≤ k.)", "options": ["5", "4", "6", "7"], "answer": 2, "explanation": "'BCABBB' (indices 2–7) has 4 B's and 2 others → replace C and A → 'BBBBBB', length 6. A 7-letter window like 'ABCABBB' has 4 B's and 3 others, needing 3 replacements. For 'A', the best is 'AABCA' → 3 A's + 2 others = 5, which is beaten by the B window.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-207", "question": "What is the length of the longest contiguous subarray of [0, 1, 1, 0, 1, 1, 1, 0, 0, 0] with an equal number of 0s and 1s? (Map 0 to −1 and look for repeated prefix sums.)", "options": ["8", "6", "4", "10"], "answer": 3, "explanation": "With 0 → −1 the prefix sums are −1, 0, 1, 0, 1, 2, 3, 2, 1, 0. The sum 0 first occurs at the start (index −1) and last at index 9, so the WHOLE array has five 0s and five 1s: length 10. Storing the LAST occurrence of each sum instead of the first finds only shorter windows.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-208", "question": "What is the maximum sum of a non-empty contiguous subarray of the CIRCULAR array [5, −8, 3, 4, −2, 6, −9, 7] (a subarray may wrap from the end to the start)?", "options": ["15", "11", "12", "14"], "answer": 0, "explanation": "Linear Kadane gives 3 + 4 − 2 + 6 = 11. The wrap-around best is total − (minimum subarray): total = 6 and the minimum subarray is just [−9], so 6 − (−9) = 15, i.e. every element except −9: 7, 5, −8, 3, 4, −2, 6. Answer max(11, 15) = 15. '12' takes only 7 + 5; '11' ignores wrapping.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-209", "question": "What is the maximum product of a non-empty contiguous subarray of [2, −3, 0, −2, −4, 3, −1]?", "options": ["8", "24", "6", "2"], "answer": 1, "explanation": "Track both the max and min product ending at each index (a negative times the min can become the max). After the 0 resets: −2, −4 → 8; × 3 → 24; × −1 → −24 (but the min −24 is not the answer). 24 from [−2, −4, 3]. Including the trailing −1 makes the product negative; across the 0 everything is 0.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-210", "question": "What is the next lexicographic permutation of [1, 5, 8, 4, 7, 6, 5, 3, 1]?", "options": ["[1, 5, 8, 5, 7, 6, 4, 3, 1]", "[1, 5, 8, 4, 7, 6, 5, 1, 3]", "[1, 5, 8, 5, 1, 3, 4, 6, 7]", "[1, 5, 8, 6, 1, 3, 4, 5, 7]"], "answer": 2, "explanation": "Find the rightmost i with a[i] < a[i+1]: a[3] = 4 (the suffix 7 6 5 3 1 is non-increasing). Swap 4 with the smallest suffix value greater than 4, which is 5 → [1, 5, 8, 5, 7, 6, 4, 3, 1], then REVERSE the suffix to make it smallest: 1, 3, 4, 6, 7. Forgetting the reversal gives [1, 5, 8, 5, 7, 6, 4, 3, 1]; swapping 4 with 6 gives [1, 5, 8, 6, 1, 3, 4, 5, 7].", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-211", "question": "Circular route: station i gives gas[i] and driving to station i + 1 costs cost[i], with gas = [3, 1, 5, 2, 6] and cost = [4, 3, 2, 4, 2]. The greedy scan resets the start to i + 1 whenever the running tank goes negative. Which start index is returned (or −1 if no full loop is possible)?", "options": ["3", "−1", "0", "2"], "answer": 3, "explanation": "Total gas 17 ≥ total cost 15, so a solution exists. Net gains: −1, −2, 3, −2, 4. From 0: −1 < 0 → restart at 1; −2 < 0 → restart at 2; 3, 1, 5 stays ≥ 0 → start 2. Checking the wrap: 5 + (−1) + (−2) = 2 ≥ 0. Starting at 3 fails at once (2 − 4 < 0) and 0 fails immediately (3 − 4 < 0). Index 4 would also complete the loop, but the greedy returns the first start after the last reset, 2.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-212", "question": "A monotonic stack removes duplicate letters so that each letter appears exactly once and the result is the lexicographically SMALLEST possible subsequence. What is the result for 'dbcabdc'?", "options": ["abdc", "abcd", "bcad", "dbca"], "answer": 0, "explanation": "Pop a larger letter on top only if it appears again later. d is pushed; b pops d (d reappears at 5); c is pushed → [b, c]; a pops c and b (both reappear) → [a]; then b and d are pushed → [a, b, d]; the final c cannot pop d because no d comes later → 'abdc'. 'abcd' is impossible: after the last d (index 5) only c follows, so d must come before the final c.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-213", "question": "20 keys are hashed independently and uniformly into 100 slots. What is the EXPECTED number of colliding pairs (unordered pairs of keys that land in the same slot)?", "options": ["0.2", "1.9", "2.0", "0.19"], "answer": 1, "explanation": "There are C(20, 2) = 190 pairs and each collides with probability 1/100, so by linearity of expectation the expected count is 1.9. '2.0' uses 20²/2 instead of 20·19/2; '0.2' divides the number of keys by the number of slots, which is the load factor, not a collision count.", "difficulty": "very-hard", "source": "Product company OA"},
  {"id": "cs-dsa-linear-214", "question": "How many contiguous subarrays of [1, 3, 2, 4, 6, 5] satisfy max − min ≤ 2? (Two monotonic deques shrink the window from the left.)", "options": ["12", "13", "14", "16"], "answer": 2, "explanation": "Count the valid windows ending at each right end r: r=0 [1]: 1; r=1 [1,3], [3]: 2; r=2 [1,3,2], [3,2], [2]: 3; r=3 [3,2,4], [2,4], [4]: 3 ([1,3,2,4] has spread 3); r=4 [4,6], [6]: 2; r=5 [4,6,5], [6,5], [5]: 3. Total 1 + 2 + 3 + 3 + 2 + 3 = 14. Because a valid window stays valid when shrunk, a two-pointer window adds (r − l + 1) per step.", "difficulty": "very-hard", "source": "Product company OA"},
];

export default questions;
